        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'おとうとは [年下]です。', '年下', 'としした', '"[\"としした\", \"としうえ\", \"ねんした\", \"ねんげ\"]"', '年下 (nhỏ tuổi hơn) đọc là としした.', 1, NOW()),
        (v_ch_id, 'READING', 'かいだんで [上がって]ください。', '上がって', 'あがって', '"[\"あがって\", \"さがって\", \"のぼって\", \"はいって\"]"', '上がって (đi lên tầng) đọc là あがって.', 2, NOW()),
        (v_ch_id, 'READING', 'つくえの [上に] なにが ありますか。', '上に', 'うえに', '"[\"うえに\", \"したに\", \"なかに\", \"そばに\"]"', '上に (ở bên trên) đọc là うえに.', 3, NOW()),
        (v_ch_id, 'READING', '二ばんホームに [下りの] でんしゃが きます。', '下りの', 'くだりの', '"[\"くだりの\", \"のぼりの\", \"さがるの\", \"したりの\"]"', '下り (tàu xuôi / chiều về) đọc là くだり.', 4, NOW()),
        (v_ch_id, 'READING', 'わたしの しゅみは [水上]スキーです。', '水上', 'すいじょう', '"[\"すいじょう\", \"みずうえ\", \"すいうえ\", \"みずじょう\"]"', '水上スキー (lướt ván nước): chữ 上 đọc là じょう (すいじょう).', 5, NOW()),
        (v_ch_id, 'READING', 'きょうは [一日中] あつかったです。', '一日中', 'いちにちじゅう', '"[\"いちにちじゅう\", \"ついたちちゅう\", \"いちにちなか\", \"ひじゅう\"]"', '一日中 (suốt cả ngày) đọc là いちにちじゅう.', 6, NOW()),
        (v_ch_id, 'READING', '[左右]を よく みて おうだんほどうを わたってください。', '左右', 'さゆう', '"[\"さゆう\", \"ひだりみぎ\", \"みぎひだり\", \"さこう\"]"', '左右 (trái phải) đọc âm On là さゆう.', 7, NOW()),
        (v_ch_id, 'READING', 'やまぐちせんせいは いま [外出]しています。', '外出', 'がいしゅつ', '"[\"がいしゅつ\", \"そとで\", \"そとしゅつ\", \"がいしゅ\"]"', '外出 (đi ra ngoài) đọc là がいしゅつ.', 8, NOW()),
        (v_ch_id, 'READING', 'まどの [内側]も よく ふいてください。', '内側', 'うちがわ', '"[\"うちがわ\", \"ないがわ\", \"そとがわ\", \"なかそば\"]"', '内側 (phía bên trong) đọc là うちがわ.', 9, NOW()),
        (v_ch_id, 'READING', 'このかどを [右に] まがってください。', '右に', 'みぎに', '"[\"みぎに\", \"ひだりに\", \"うえに\", \"まえに\"]"', '右に (rẽ bên phải) đọc là みぎに.', 10, NOW()),
        (v_ch_id, 'WRITING', '[としうえ]の 人と けっこんしたいです。Kanji là:', 'としうえ', '年上', '"[\"年上\", \"歳上\", \"年中\", \"年高\"]"', 'としうえ (người lớn tuổi hơn) viết là 年上.', 1, NOW()),
        (v_ch_id, 'WRITING', 'あついですから [そと]に でたくないです。Kanji là:', 'そと', '外', '"[\"外\", \"内\", \"中\", \"処\"]"', 'そと (bên ngoài) viết chữ Hán là 外.', 2, NOW()),
        (v_ch_id, 'WRITING', 'いすの [した]に ねこが います。Kanji là:', 'した', '下', '"[\"下\", \"上\", \"不\", \"正\"]"', 'した (bên dưới) viết chữ Hán là 下.', 3, NOW()),
        (v_ch_id, 'WRITING', 'せいせきが [さ]がりました。Kanji là:', 'さ', '下', '"[\"下\", \"降\", \"落\", \"少\"]"', 'さがる (giảm xuống, hạ xuống) viết là 下がる.', 4, NOW()),
        (v_ch_id, 'WRITING', 'つくえの [みぎ]がわに たってください。Kanji là:', 'みぎ', '右', '"[\"右\", \"左\", \"石\", \"若\"]"', 'みぎ (bên phải) viết chữ Hán là 右.', 5, NOW()),
        (v_ch_id, 'WRITING', 'わたしは [ひだり]ききです。Kanji là:', 'ひだり', '左', '"[\"左\", \"右\", \"在\", \"友\"]"', 'ひだり (bên trái) viết chữ Hán là 左.', 6, NOW()),
        (v_ch_id, 'WRITING', 'デパートで [じょうげ]セットを かいました。Kanji là:', 'じょうげ', '上下', '"[\"上下\", \"上中\", \"下上\", \"高低\"]"', 'じょうげ (trên dưới / bộ quần áo) viết là 上下.', 7, NOW()),
        (v_ch_id, 'WRITING', 'なつやすみに [こくない]を りょこうしました。Kanji là:', 'こくない', '国内', '"[\"国内\", \"国中\", \"国外\", \"国間\"]"', 'こくない (trong nước) viết là 国内.', 8, NOW()),
        (v_ch_id, 'WRITING', 'かばんの [なか]に 水が あります。Kanji là:', 'なか', '中', '"[\"中\", \"内\", \"央\", \"仲\"]"', 'なか (bên trong) viết chữ Hán là 中.', 9, NOW()),
        (v_ch_id, 'WRITING', 'やまだせんせいは いま [じゅぎょうちゅう]です。Kanji là:', 'じゅぎょうちゅう', '授業中', '"[\"授業中\", \"授業内\", \"授業間\", \"受業中\"]"', 'じゅぎょうちゅう (đang trong giờ học) dùng chữ 中.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 どんな かんじが できますか (Ghép nét tạo chữ Hán)', 'Quan sát các nét bút thành phần rời rạc trong tranh và suy luận xem chúng ghép lại thành chữ Hán nào.', '/assets/kanji/n5/minigames/chap5_minigame_p52.webp', '"{\"example\": {\"prompt\": \"れい: 丨 + 一 + 一\", \"answer\": \"上\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. 一 + 丨 + 丶\", \"options\": [\"下\", \"上\", \"十\", \"土\"], \"answer\": \"下\", \"explanation\": \"Nét ngang dài ở trên, nét sổ và nét chấm ở dưới tạo thành chữ 下 (HẠ - phía dưới).\"}, {\"id\": 2, \"prompt\": \"2. 丨 + 冂 + 一 + 丨\", \"options\": [\"中\", \"内\", \"口\", \"日\"], \"answer\": \"中\", \"explanation\": \"Hình chữ nhật có nét sổ dọc xuyên chính giữa tâm tạo thành chữ 中 (TRUNG - bên trong).\"}, {\"id\": 3, \"prompt\": \"3. 夕 + 卜\", \"options\": [\"外\", \"多\", \"夕\", \"名\"], \"answer\": \"外\", \"explanation\": \"Bộ Tịch (夕) kết hợp với bộ Bặc (卜) tạo thành chữ 外 (NGOẠI - bên ngoài).\"}, {\"id\": 4, \"prompt\": \"4. 一 + 丿 + 口\", \"options\": [\"右\", \"左\", \"石\", \"友\"], \"answer\": \"右\", \"explanation\": \"Nét ngang phiệt kết hợp bộ Khẩu (口) tạo thành chữ 右 (HỮU - bên phải). Theo đáp án sách: 4. 右.\"}, {\"id\": 5, \"prompt\": \"5. 冂 + 人 (丿 + 丶)\", \"options\": [\"内\", \"肉\", \"円\", \"中\"], \"answer\": \"内\", \"explanation\": \"Bộ Quynh (冂) bao quanh nét phẩy và nét chấm tạo thành chữ 内 (NỘI - bên trong).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 えを みて かんじを かきましょう (Quan sát tranh căn phòng)', 'Quan sát vị trí các đồ vật và con vật trong bức tranh căn phòng rồi chọn chữ Hán chính xác điền vào ô trống.', '/assets/kanji/n5/minigames/chap5_minigame_p53.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"1. テーブルの [ ? ] に [ ? ]びんが あります。\", \"options\": [\"上 / 花\", \"下 / 花\", \"中 / 木\", \"外 / 石\"], \"answer\": \"上 / 花\", \"explanation\": \"Trên mặt bàn có bình hoa: テーブルの上に花びんがあります。\"}, {\"id\": 2, \"prompt\": \"2. うちの [ ? ] に ねこが [ ? ]ひき います。\", \"options\": [\"外 / 二\", \"中 / 一\", \"上 / 三\", \"下 / 二\"], \"answer\": \"外 / 二\", \"explanation\": \"Bên ngoài bậu cửa sổ có 2 chú mèo: うちの外にねこが二ひきいます。\"}, {\"id\": 3, \"prompt\": \"3. ベッドの [ ? ] に いぬが [ ? ]ぴき います。\", \"options\": [\"上 / 一\", \"下 / 二\", \"中 / 一\", \"外 / 三\"], \"answer\": \"上 / 一\", \"explanation\": \"Trên giường có 1 chú chó đang nằm ngủ: ベッドの上にいぬが一ぴきいます。\"}, {\"id\": 4, \"prompt\": \"4. うちの [ ? ] に おんなのこが [ ? ] います。\", \"options\": [\"中 / 一人\", \"外 / 二人\", \"上 / 一人\", \"下 / 二人\"], \"answer\": \"中 / 一人\", \"explanation\": \"Trong nhà có 1 bé gái đang ôm gấu bông: うちの中におんなのこが一人います。\"}, {\"id\": 5, \"prompt\": \"5. へやの [ ? ] の いすの [ ? ] に くつが [ ? ] あります。\", \"options\": [\"中 / 下 / 一そく\", \"外 / 上 / 二そく\", \"中 / 上 / 一そく\", \"内 / 中 / 三そく\"], \"answer\": \"中 / 下 / 一そく\", \"explanation\": \"Dưới chân ghế trong phòng có 1 đôi giày: へやの中のいすの下にくつが一そくあります。\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 かんじを かきましょう (Đoạn văn ''Trường học của tôi'')', 'Đọc bài văn ngắn giới thiệu về trường học và chọn chữ Hán tương ứng với đầy đủ 11 vị trí gạch chân từ ① đến ⑪.', '/assets/kanji/n5/minigames/chap5_minigame_p53.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① がくせいは かいだんで [あがり] ます\", \"options\": [\"上がります\", \"下がります\", \"出ます\", \"入ります\"], \"answer\": \"上がります\", \"explanation\": \"あがります viết bằng chữ 上: 上がります (đi lên lầu).\"}, {\"id\": 2, \"prompt\": \"② がっこうの [なか] に じどうはんばいきが あります\", \"options\": [\"中\", \"内\", \"外\", \"間\"], \"answer\": \"中\", \"explanation\": \"なかに viết là 中に (bên trong).\"}, {\"id\": 3, \"prompt\": \"③ [みぎ] が おとこのひとの トイレです\", \"options\": [\"右\", \"左\", \"外\", \"上\"], \"answer\": \"右\", \"explanation\": \"みぎ viết là 右 (bên phải).\"}, {\"id\": 4, \"prompt\": \"④ みぎが おとこの [ひと] の トイレです\", \"options\": [\"人\", \"男\", \"子\", \"友\"], \"answer\": \"人\", \"explanation\": \"おとこのひと viết là 男の人 (người nam, đàn ông).\"}, {\"id\": 5, \"prompt\": \"⑤ [ひだり] が おんなのひとの トイレです\", \"options\": [\"左\", \"右\", \"外\", \"下\"], \"answer\": \"左\", \"explanation\": \"ひだり viết là 左 (bên trái).\"}, {\"id\": 6, \"prompt\": \"⑥ ひだりが おんなの [ひと] の トイレです\", \"options\": [\"人\", \"女\", \"子\", \"友\"], \"answer\": \"人\", \"explanation\": \"おんなのひと viết là 女の人 (người nữ, phụ nữ).\"}, {\"id\": 7, \"prompt\": \"⑦ こう [ない] は きんえんです (Trong khuôn viên trường)\", \"options\": [\"内\", \"中\", \"校\", \"外\"], \"answer\": \"内\", \"explanation\": \"こうない viết là 校内 (trong khuôn viên trường).\"}, {\"id\": 8, \"prompt\": \"⑧ きょうしつの [そと] の ベランダで やすみます\", \"options\": [\"外\", \"中\", \"内\", \"下\"], \"answer\": \"外\", \"explanation\": \"そと viết là 外 (bên ngoài ban công).\"}, {\"id\": 9, \"prompt\": \"⑨ ベランダから [した] を みます\", \"options\": [\"下\", \"上\", \"中\", \"外\"], \"answer\": \"下\", \"explanation\": \"した viết là 下 (phía dưới sân).\"}, {\"id\": 10, \"prompt\": \"⑩ [ひと] が たくさん あるいています\", \"options\": [\"人\", \"男\", \"女\", \"生\"], \"answer\": \"人\", \"explanation\": \"ひと viết là 人 (nhiều người đang đi lại).\"}, {\"id\": 11, \"prompt\": \"⑪ [いちにちじゅう] がっこうに います\", \"options\": [\"一日中\", \"毎日\", \"休日\", \"今週\"], \"answer\": \"一日中\", \"explanation\": \"いちにちじゅう viết là 一日中 (suốt cả một ngày).\"}]}"', 3, NOW());
