        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'あした [学校]へ いきます。', '学校', 'がっこう', '"[\"がっこう\", \"がくこう\", \"がっつこう\", \"だいがく\"]"', '学校 (trường học) đọc là がっこう.', 1, NOW()),
        (v_ch_id, 'READING', 'たなか[先生]は やさしいです。', '先生', 'せんせい', '"[\"せんせい\", \"せんじょう\", \"さきせい\", \"ぜんせい\"]"', '先生 (thầy giáo) đọc là せんせい.', 2, NOW()),
        (v_ch_id, 'READING', 'わたしは [学生]です。', '学生', 'がくせい', '"[\"がくせい\", \"がくしょう\", \"がっせい\", \"がくせん\"]"', '学生 (học sinh) đọc là がくせい.', 3, NOW()),
        (v_ch_id, 'READING', 'お[名前]は なんですか。', '名前', 'なまえ', '"[\"なまえ\", \"めいぜん\", \"みょうまえ\", \"なまえん\"]"', '名前 (tên) đọc là なまえ.', 4, NOW()),
        (v_ch_id, 'READING', 'かんじの [漢字]を れんしゅうします。', '漢字', 'かんじ', '"[\"かんじ\", \"かんし\", \"からじ\", \"かんち\"]"', '漢字 (chữ Hán) đọc là かんじ.', 5, NOW()),
        (v_ch_id, 'READING', 'この[本]は おもしろいです。', '本', 'ほん', '"[\"ほん\", \"ぼん\", \"ぽん\", \"もと\"]"', '本 (quyển sách) đọc là ほん.', 6, NOW()),
        (v_ch_id, 'READING', '[体]の ちょうしが いいです。', '体', 'からだ', '"[\"からだ\", \"たい\", \"てい\", \"しん\"]"', '体 (cơ thể) đọc âm Kun là からだ.', 7, NOW()),
        (v_ch_id, 'READING', '[大学]で べんきょうします。', '大学', 'だいがく', '"[\"だいがく\", \"おおがく\", \"たいがく\", \"だいがっこう\"]"', '大学 (đại học) đọc là だいがく.', 8, NOW()),
        (v_ch_id, 'READING', '[生年月日]を かいてください。', '生年月日', 'せいねんがっぴ', '"[\"せいねんがっぴ\", \"しょうねんがっぴ\", \"いきねんつきひ\", \"せいねんつきひ\"]"', '生年月日 (ngày tháng năm sinh) đọc là せいねんがっぴ.', 9, NOW()),
        (v_ch_id, 'READING', '[有名]な レストランへ いきました。', '有名', 'ゆうめい', '"[\"ゆうめい\", \"ありな\", \"うめい\", \"ゆうな\"]"', '有名 (nổi tiếng) đọc là ゆうめい.', 10, NOW()),
        (v_ch_id, 'WRITING', 'にほんの [がっこう]で まなびます。Kanji là:', 'がっこう', '学校', '"[\"学校\", \"学効\", \"学交\", \"楽校\"]"', 'がっこう viết là 学校.', 1, NOW()),
        (v_ch_id, 'WRITING', 'すずき[せんせい]に あいました。Kanji là:', 'せんせい', '先生', '"[\"先生\", \"先正\", \"前生\", \"仙生\"]"', 'せんせい viết là 先生.', 2, NOW()),
        (v_ch_id, 'WRITING', '[がくせい]が たくさん います。Kanji là:', 'がくせい', '学生', '"[\"学生\", \"学正\", \"楽生\", \"校生\"]"', 'がくせい viết là 学生.', 3, NOW()),
        (v_ch_id, 'WRITING', '[なまえ]を かいてください。Kanji là:', 'なまえ', '名前', '"[\"名前\", \"名全\", \"名先\", \"明前\"]"', 'なまえ viết là 名前.', 4, NOW()),
        (v_ch_id, 'WRITING', 'きれいな [じ]を かきます。Kanji là:', 'じ', '字', '"[\"字\", \"学\", \"子\", \"寺\"]"', 'じ (chữ viết) viết là 字.', 5, NOW()),
        (v_ch_id, 'WRITING', 'としょかんで [ほん]を よみます。Kanji là:', 'ほん', '本', '"[\"本\", \"木\", \"体\", \"休\"]"', 'ほん (sách) viết chữ Hán là 本.', 6, NOW()),
        (v_ch_id, 'WRITING', '[からだ]に きを つけてください。Kanji là:', 'からだ', '体', '"[\"体\", \"休\", \"本\", \"木\"]"', 'からだ viết chữ Hán là 体.', 7, NOW()),
        (v_ch_id, 'WRITING', '[だいがく]に はいります。Kanji là:', 'だいがく', '大学', '"[\"大学\", \"太学\", \"犬学\", \"大校\"]"', 'だいがく viết là 大学.', 8, NOW()),
        (v_ch_id, 'WRITING', '[かんじ]の テストが あります。Kanji là:', 'かんじ', '漢字', '"[\"漢字\", \"漢寺\", \"漢事\", \"幹字\"]"', 'かんじ viết là 漢字.', 9, NOW()),
        (v_ch_id, 'WRITING', '[たいそう]を します。Kanji là:', 'たいそう', '体操', '"[\"体操\", \"体そう\", \"大操\", \"身操\"]"', 'たいそう (thể dục) dùng chữ 体 (体操).', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 かんじの たしざんです (Phép cộng bộ thủ tạo chữ Kanji)', 'Ghép các bộ thủ theo công thức cộng trong sách để tạo thành từ vựng có nghĩa tương ứng (đầy đủ 6 câu).', '/assets/kanji/n5/minigames/chap6_minigame_p63.webp', '"{\"example\": {\"prompt\": \"れい: (木 + 交) + ちょう\", \"answer\": \"校ちょう (こうちょう)\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. (夕 + 口) + まえ = [ ? ] まえ ( [ ? ] まえ )\", \"options\": [\"名まえ (なまえ)\", \"右まえ (みぎまえ)\", \"見まえ (みまえ)\", \"口まえ (くちまえ)\"], \"answer\": \"名まえ (なまえ)\", \"explanation\": \"夕 + 口 = chữ 名 (Danh trong 名前 - なまえ - tên họ).\"}, {\"id\": 2, \"prompt\": \"2. も + (宀 + 子) = も [ ? ] ( も [ ? ] )\", \"options\": [\"も字 (もじ)\", \"も本 (もほん)\", \"も名 (もな)\", \"も体 (もたい)\"], \"answer\": \"も字 (もじ)\", \"explanation\": \"宀 + 子 = chữ 字 (Tự trong 文字/も字 - もじ - ký tự, con chữ).\"}, {\"id\": 3, \"prompt\": \"3. (丿 + 丨 + 木 + 一) + 力 = [ ? ] ( [ ? ] )\", \"options\": [\"体力 (たいりょく)\", \"休力 (きゅうりょく)\", \"本力 (ほんりき)\", \"体本 (たいほん)\"], \"answer\": \"体力 (たいりょく)\", \"explanation\": \"丿 + 丨 + 木 + 一 = 体 (Thể), cộng thêm 力 (Lực) = 体力 (たいりょく - thể lực). Theo đáp án sách: 3. 体力 (たいりょく).\"}, {\"id\": 4, \"prompt\": \"4. (口 + 一) + (木 + 一) = [ ? ] ( [ ? ] )\", \"options\": [\"日本 (にほん)\", \"白木 (しらき)\", \"目本 (めほん)\", \"田林 (たばやし)\"], \"answer\": \"日本 (にほん)\", \"explanation\": \"口 + 一 = 日, 木 + 一 = 本 -> Ghép lại thành 日本 (にほん - Nhật Bản). Theo đáp án sách: 4. 日本 (にほん).\"}, {\"id\": 5, \"prompt\": \"5. (ツ + 冖 + 子) + (丿 + 一 + 丨 + 一 + 一) = [ ? ] ( [ ? ] )\", \"options\": [\"学生 (がくせい)\", \"先生 (せんせい)\", \"学校 (がっこう)\", \"生徒 (せいと)\"], \"answer\": \"学生 (がくせい)\", \"explanation\": \"Vế 1: 学 (ツ + 冖 + 子), Vế 2: 生 (丿 + 一 + 丨 + 一 + 一) -> Tạo thành 学生 (がくせい - học sinh). Theo đáp án sách: 5. 学生 (がくせい).\"}, {\"id\": 6, \"prompt\": \"6. (丿 + 土 + 儿) + (丿 + 一 + 丨 + 一 + 一) = [ ? ] ( [ ? ] )\", \"options\": [\"先生 (せんせい)\", \"学生 (がくせい)\", \"校生 (こうせい)\", \"先輩 (せんぱい)\"], \"answer\": \"先生 (せんせい)\", \"explanation\": \"Vế 1: 先 (丿 + 土 + 儿), Vế 2: 生 (丿 + 一 + 丨 + 一 + 一) -> Tạo thành 先生 (せんせい - giáo viên). Theo đáp án sách: 6. 先生 (せんせい).\"}]}"', 3, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 がっこうの えを みて かんじを かきましょう (Quan sát sơ đồ trường học)', 'Quan sát bức tranh trường học và lớp học, chọn chữ Hán chuẩn xác tương ứng với đầy đủ 6 vị trí ① đến ⑥.', '/assets/kanji/n5/minigames/chap6_minigame_p62.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"Vị trí ①: Toàn bộ tòa nhà trường học chính\", \"options\": [\"学校\", \"学生\", \"高校\", \"大学\"], \"answer\": \"学校\", \"explanation\": \"Ngôi trường viết là 学校 (がっこう).\"}, {\"id\": 2, \"prompt\": \"Vị trí ②: Nhà thi đấu thể dục thể thao ([ ? ] いくかん)\", \"options\": [\"体\", \"休\", \"本\", \"生\"], \"answer\": \"体\", \"explanation\": \"たいいくかん viết là 体育館 (chữ 体 trong 体力, 体育).\"}, {\"id\": 3, \"prompt\": \"Vị trí ③: Học sinh nữ giơ tay phát biểu trong lớp\", \"options\": [\"学生\", \"先生\", \"高校生\", \"子供\"], \"answer\": \"学生\", \"explanation\": \"Học sinh/sinh viên viết là 学生 (がくせい).\"}, {\"id\": 4, \"prompt\": \"Vị trí ④: Quyển sách giáo trình đặt trên bàn học\", \"options\": [\"本\", \"字\", \"手\", \"休\"], \"answer\": \"本\", \"explanation\": \"Quyển sách viết là 本 (ほん). Theo đáp án sách: ④ 本.\"}, {\"id\": 5, \"prompt\": \"Vị trí ⑤: Chữ viết chữ Hán trên bảng đen (かん [ ? ])\", \"options\": [\"字\", \"本\", \"名\", \"文\"], \"answer\": \"字\", \"explanation\": \"Chữ Hán trên bảng viết là 漢字 (かんじ), chữ 字. Theo đáp án sách: ⑤ かん字.\"}, {\"id\": 6, \"prompt\": \"Vị trí ⑥: Giáo viên đang đứng giảng bài bên bảng đen\", \"options\": [\"先生\", \"学生\", \"校長\", \"大人\"], \"answer\": \"先生\", \"explanation\": \"Cô giáo giảng bài là 先生 (せんせい).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 おはなみの さくぶん (Đoạn văn ngắm hoa anh đào)', 'Đọc bài văn ngắm hoa anh đào cùng thầy cô và bạn bè, chọn chữ Hán đúng cho đầy đủ 9 vị trí từ ① đến ⑨.', '/assets/kanji/n5/minigames/chap6_minigame_p62.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① [せんげつ] アークアカデミーで おはなみを しました\", \"options\": [\"先月\", \"今月\", \"来月\", \"毎月\"], \"answer\": \"先月\", \"explanation\": \"せんげつ viết là 先月 (tháng trước).\"}, {\"id\": 2, \"prompt\": \"② お [はな] みを しました\", \"options\": [\"花\", \"月\", \"見\", \"木\"], \"answer\": \"花\", \"explanation\": \"おはなみ viết là お花み (ngắm hoa anh đào).\"}, {\"id\": 3, \"prompt\": \"③ [せんせい] が じゅうにんと...\", \"options\": [\"先生\", \"学生\", \"校長\", \"先月\"], \"answer\": \"先生\", \"explanation\": \"せんせい viết là 先生 (thầy cô giáo).\"}, {\"id\": 4, \"prompt\": \"④ せんせいが [じゅうにん] と...\", \"options\": [\"十人\", \"三人\", \"二十人\", \"千人\"], \"answer\": \"十人\", \"explanation\": \"じゅうにん viết là 十人 (10 người).\"}, {\"id\": 5, \"prompt\": \"⑤ [がくせい] が さんじゅうにん いました\", \"options\": [\"学生\", \"先生\", \"高校生\", \"学校\"], \"answer\": \"学生\", \"explanation\": \"がくせい viết là 学生 (học sinh, học viên).\"}, {\"id\": 6, \"prompt\": \"⑥ がくせいが [さんじゅうにん] いました\", \"options\": [\"三十人\", \"三人\", \"十人\", \"三十\"], \"answer\": \"三十人\", \"explanation\": \"さんじゅうにん viết là 三十人 (30 người).\"}, {\"id\": 7, \"prompt\": \"⑦ [こう] ちょうせんせいの いなりずしを たべました\", \"options\": [\"校\", \"学\", \"高\", \"長\"], \"answer\": \"校\", \"explanation\": \"こうちょう viết là 校ちょう (thầy hiệu trưởng).\"}, {\"id\": 8, \"prompt\": \"⑧ [にほん] へ きて はじめて さくらを みました\", \"options\": [\"日本\", \"毎日\", \"休日\", \"本\"], \"answer\": \"日本\", \"explanation\": \"にほん viết là 日本 (Nhật Bản).\"}, {\"id\": 9, \"prompt\": \"⑨ とても たのしい [ひ] でした\", \"options\": [\"日\", \"月\", \"年\", \"時\"], \"answer\": \"日\", \"explanation\": \"ひ viết là 日 (ngày, một ngày vui vẻ).\"}]}"', 2, NOW());
