        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '[大きい] いぬが います。', '大きい', 'おおきい', '"[\"おおきい\", \"だいきい\", \"たいきい\", \"ふとい\"]"', '大きい (to lớn) đọc là おおきい.', 1, NOW()),
        (v_ch_id, 'READING', '[小さい] ねこが かわいらしいです。', '小さい', 'ちいさい', '"[\"ちいさい\", \"しょうさい\", \"こさい\", \"すくない\"]"', '小さい (nhỏ nhắn) đọc là ちいさい.', 2, NOW()),
        (v_ch_id, 'READING', 'このやまは とても [高い]です。', '高い', 'たかい', '"[\"たかい\", \"こうい\", \"ひろい\", \"ながい\"]"', '高い (cao lớn) đọc là たかい.', 3, NOW()),
        (v_ch_id, 'READING', 'しんゆうの [友達]と あそびます。', '友達', 'ともだち', '"[\"ともだち\", \"ゆうだち\", \"ほうたち\", \"ともたち\"]"', '友達 (bạn bè) đọc là ともだち.', 4, NOW()),
        (v_ch_id, 'READING', 'へやに [入って]ください。', '入って', 'はいって', '"[\"はいって\", \"いって\", \"でて\", \"たって\"]"', '入って (bước vào) đọc là はいって.', 5, NOW()),
        (v_ch_id, 'READING', 'えきから [出て]きました。', '出て', 'でて', '"[\"でて\", \"だして\", \"はいって\", \"いって\"]"', '出て (đi ra) đọc là でて.', 6, NOW()),
        (v_ch_id, 'READING', 'がっこうの [正門]で まちます。', '正門', 'せいもん', '"[\"せいもん\", \"しょうもん\", \"ただもん\", \"せいかど\"]"', '正門 (cổng chính) đọc là せいもん.', 7, NOW()),
        (v_ch_id, 'READING', '[高校生]に なりました。', '高校生', 'こうこうせい', '"[\"こうこうせい\", \"たかこうせい\", \"こうがくせい\", \"こうたかせい\"]"', '高校生 (học sinh cấp 3) đọc là こうこうせい.', 8, NOW()),
        (v_ch_id, 'READING', '[入り口]は あちらです。', '入り口', 'いりぐち', '"[\"いりぐち\", \"はいりくち\", \"にゅうこう\", \"いりこう\"]"', '入り口 (cửa vào) đọc là いりぐち.', 9, NOW()),
        (v_ch_id, 'READING', '[出口]は こちらです。', '出口', 'でぐち', '"[\"でぐち\", \"だしくち\", \"しゅつこう\", \"でこう\"]"', '出口 (cửa ra) đọc là でぐち.', 10, NOW()),
        (v_ch_id, 'WRITING', '[おおきい] こえで はなします。Kanji là:', 'おおきい', '大きい', '"[\"大きい\", \"太い\", \"犬きい\", \"高きい\"]"', 'おおきい viết là 大きい.', 1, NOW()),
        (v_ch_id, 'WRITING', '[ちいさい] こどもが います。Kanji là:', 'ちいさい', '小さい', '"[\"小さい\", \"少さい\", \"微さい\", \"短さい\"]"', 'ちいさい viết là 小さい.', 2, NOW()),
        (v_ch_id, 'WRITING', '[たかい] ビルが あります。Kanji là:', 'たかい', '高い', '"[\"高い\", \"大い\", \"長い\", \"広かい\"]"', 'たかい viết là 高い.', 3, NOW()),
        (v_ch_id, 'WRITING', '[ともだち]と りょこうします。Kanji là:', 'ともだち', '友達', '"[\"友達\", \"友立\", \"有達\", \"共達\"]"', 'ともだち viết là 友達.', 4, NOW()),
        (v_ch_id, 'WRITING', 'おふろに [はい]ります。Kanji là:', 'はい', '入', '"[\"入\", \"人\", \"八\", \"込\"]"', 'はいる (bước vào) viết chữ Hán là 入る.', 5, NOW()),
        (v_ch_id, 'WRITING', 'うちを [で]ます。Kanji là:', 'で', '出', '"[\"出\", \"山\", \"生\", \"去\"]"', 'でる (rời khỏi) viết chữ Hán là 出る.', 6, NOW()),
        (v_ch_id, 'WRITING', 'えきの [もん]を とおります。Kanji là:', 'もん', '門', '"[\"門\", \"問\", \"開\", \"閉\"]"', 'もん (cổng) viết chữ Hán là 門.', 7, NOW()),
        (v_ch_id, 'WRITING', '[こうこう]へ いきます。Kanji là:', 'こうこう', '高校', '"[\"高校\", \"高好\", \"向校\", \"公校\"]"', 'こうこう (trường THPT) viết là 高校.', 8, NOW()),
        (v_ch_id, 'WRITING', '[いりぐち]で チケットを みせます。Kanji là:', 'いりぐち', '入口', '"[\"入口\", \"人ロ\", \"八口\", \"進口\"]"', 'いりぐち viết là 入口.', 9, NOW()),
        (v_ch_id, 'WRITING', '[でぐち]を さがします。Kanji là:', 'でぐち', '出口', '"[\"出口\", \"山口\", \"生口\", \"去口\"]"', 'でぐち viết là 出口.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 にゅうがくしきの さくぶん (Lễ khai giảng nhập học)', 'Đọc bài văn kể về ngày lễ khai giảng nhập học, điền đầy đủ 20 chữ Hán tương ứng từ ① đến ⑳.', '/assets/kanji/n5/minigames/chap7_minigame_p70.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① [にゅうがく] しき でした (Lễ nhập học)\", \"options\": [\"入学\", \"大学\", \"見学\", \"休学\"], \"answer\": \"入学\", \"explanation\": \"にゅうがく viết là 入学 (Nhập học).\"}, {\"id\": 2, \"prompt\": \"② えきは とても [おお] きいですから (Nhà ga rất to lớn)\", \"options\": [\"大\", \"小\", \"高\", \"広\"], \"answer\": \"大\", \"explanation\": \"おおきい viết là 大きい, chữ 大.\"}, {\"id\": 3, \"prompt\": \"③ [でぐち] が わかりませんでした (Không biết lối ra)\", \"options\": [\"出口\", \"入口\", \"門\", \"山口\"], \"answer\": \"出口\", \"explanation\": \"でぐち viết là 出口 (cửa ra, lối ra).\"}, {\"id\": 4, \"prompt\": \"④ [こうこうせい] に ききました (Hỏi học sinh cấp 3)\", \"options\": [\"高校生\", \"大学生\", \"先生\", \"小学生\"], \"answer\": \"高校生\", \"explanation\": \"こうこうせい viết là 高校生 (học sinh cấp 3).\"}, {\"id\": 5, \"prompt\": \"⑤ 5ふん あるいて [がっこう] に つきました\", \"options\": [\"学校\", \"高校\", \"大学\", \"校門\"], \"answer\": \"学校\", \"explanation\": \"がっこう viết là 学校 (ngôi trường).\"}, {\"id\": 6, \"prompt\": \"⑥ きょうしつに [はい] って いすに すわりました\", \"options\": [\"入\", \"出\", \"立\", \"行\"], \"answer\": \"入\", \"explanation\": \"はいって viết là 入って (bước vào trong lớp).\"}, {\"id\": 7, \"prompt\": \"⑦ となりの [おんなのひと] と はなしを しました\", \"options\": [\"女の人\", \"男の人\", \"友達\", \"先生\"], \"answer\": \"女の人\", \"explanation\": \"おんなのひと viết là 女の人 (người bạn nữ).\"}, {\"id\": 8, \"prompt\": \"⑧ [な] まえは エンさんです\", \"options\": [\"名\", \"字\", \"本\", \"目\"], \"answer\": \"名\", \"explanation\": \"なまえ viết là 名まえ (tên họ).\"}, {\"id\": 9, \"prompt\": \"⑨ エンさんは [こうこう] を そつぎょうして\", \"options\": [\"高校\", \"大学\", \"学校\", \"中学\"], \"answer\": \"高校\", \"explanation\": \"こうこう viết là 高校 (trường cấp 3).\"}, {\"id\": 10, \"prompt\": \"⑩ [にほん] へ きました\", \"options\": [\"日本\", \"本日\", \"休日\", \"毎日\"], \"answer\": \"日本\", \"explanation\": \"にほん viết là 日本 (Nhật Bản).\"}, {\"id\": 11, \"prompt\": \"⑪ わたしと エンさんは [とも] だちに なりました\", \"options\": [\"友\", \"有\", \"右\", \"同\"], \"answer\": \"友\", \"explanation\": \"ともだち viết là 友だち (bạn bè).\"}, {\"id\": 12, \"prompt\": \"⑫ アークアカデミーを そつぎょうして [だいがく] に はいります\", \"options\": [\"大学\", \"高校\", \"学校\", \"専門\"], \"answer\": \"大学\", \"explanation\": \"だいがく viết là 大学 (trường đại học).\"}, {\"id\": 13, \"prompt\": \"⑬ だいがくに [はい] ります\", \"options\": [\"入\", \"出\", \"行\", \"来\"], \"answer\": \"入\", \"explanation\": \"はいります viết là 入ります (nhập học, thi đỗ vào).\"}, {\"id\": 14, \"prompt\": \"⑭ わたしは [だいがく] いんに はいりたいです\", \"options\": [\"大学\", \"高校\", \"学校\", \"専門\"], \"answer\": \"大学\", \"explanation\": \"だいがくいん viết là 大学院 (viện cao học).\"}, {\"id\": 15, \"prompt\": \"⑮ だいがくいんに [はい] りたいです\", \"options\": [\"入\", \"出\", \"立\", \"学\"], \"answer\": \"入\", \"explanation\": \"はいりたい viết là 入りたい (muốn bước vào).\"}, {\"id\": 16, \"prompt\": \"⑯ まだ [せん] もんちしきが ありませんから\", \"options\": [\"門\", \"問\", \"間\", \"聞\"], \"answer\": \"門\", \"explanation\": \"せんもん viết là 専門 (chuyên môn).\"}, {\"id\": 17, \"prompt\": \"⑰ これから たくさん [ほん] を よまなければ なりません\", \"options\": [\"本\", \"体\", \"木\", \"休\"], \"answer\": \"本\", \"explanation\": \"ほん viết là 本 (sách vở).\"}, {\"id\": 18, \"prompt\": \"⑱ それから [にほん] ごの べんきょうと\", \"options\": [\"日本\", \"本日\", \"毎日\", \"本\"], \"answer\": \"日本\", \"explanation\": \"にほんご viết là 日本語 (tiếng Nhật).\"}, {\"id\": 19, \"prompt\": \"⑲ [にほん] ぶんかも まなびたいです\", \"options\": [\"日本\", \"本日\", \"東日\", \"休日\"], \"answer\": \"日本\", \"explanation\": \"にほんぶんか viết là 日本文化 (văn hóa Nhật).\"}, {\"id\": 20, \"prompt\": \"⑳ にほんぶんかも [まな] びたいです\", \"options\": [\"学\", \"校\", \"生\", \"習\"], \"answer\": \"学\", \"explanation\": \"まなびたい viết là 学びたい (muốn học hỏi, chữ 学 trong 学ぶ).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 はんたいの かんじ (Cặp chữ Hán đối lập trái nghĩa)', 'Quan sát tranh minh họa đối lập và điền chữ Hán trái nghĩa tương ứng (5 câu).', '/assets/kanji/n5/minigames/chap7_minigame_p71.webp', '"{\"example\": {\"prompt\": \"れい: 上 <=> 下 (Trên bàn <=> Dưới bàn)\", \"answer\": \"下\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. [ ? ] <=> 小 (Voi mẹ to lớn <=> Voi con bé nhỏ)\", \"options\": [\"大\", \"高\", \"多\", \"長\"], \"answer\": \"大\", \"explanation\": \"Đại (大) đối lập với Tiểu (小).\"}, {\"id\": 2, \"prompt\": \"2. 子ども <=> [ ? ] (Trẻ em bé nhỏ <=> Người lớn)\", \"options\": [\"大人\", \"女の人\", \"男の人\", \"老人\"], \"answer\": \"大人\", \"explanation\": \"子ども (trẻ em) đối lập với 大人 (おとな - người lớn).\"}, {\"id\": 3, \"prompt\": \"3. [ ? ] <=> 入り口 (Lối ra mũi tên thoát <=> Lối vào)\", \"options\": [\"出口\", \"大口\", \"門\", \"窓口\"], \"answer\": \"出口\", \"explanation\": \"入り口 (lối vào) đối lập với 出口 (でぐち - lối ra).\"}, {\"id\": 4, \"prompt\": \"4. [ ? ] い <=> やすい (30,000 yên đắt đỏ <=> 100 yên giá rẻ)\", \"options\": [\"高\", \"大\", \"多\", \"新\"], \"answer\": \"高\", \"explanation\": \"やすい (rẻ) đối lập với 高い (たかい - đắt giá).\"}, {\"id\": 5, \"prompt\": \"5. 出る <=> [ ? ] る (Đi ra ngoài <=> Bước vào trong)\", \"options\": [\"入\", \"立\", \"来\", \"帰\"], \"answer\": \"入\", \"explanation\": \"出る (でる - đi ra) đối lập với 入る (はいる - đi vào).\"}]}"', 2, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
        (v_ch_id, '父', 'ちち', 'chichi', 'Bố (của mình)', 'Father', 1, NOW()),
        (v_ch_id, 'お父さん', 'おとうさん', 'otousan', 'Bố (người khác / gọi tôn kính)', 'Father', 2, NOW()),
        (v_ch_id, '母', 'はは', 'haha', 'Mẹ (của mình)', 'Mother', 3, NOW()),
        (v_ch_id, 'お母さん', 'おかあさん', 'okaasan', 'Mẹ (người khác / gọi tôn kính)', 'Mother', 4, NOW()),
        (v_ch_id, '父母', 'ふぼ', 'fubo', 'Bố mẹ, phụ mẫu', 'Parents', 5, NOW()),
        (v_ch_id, '子ども', 'こども', 'kodomo', 'Trẻ em, con cái', 'Child, children', 6, NOW()),
        (v_ch_id, '男', 'おとこ', 'otoko', 'Phái nam, đàn ông', 'Male, man', 7, NOW()),
