        (v_ch_id, '焼き鳥', 'やきとり', 'yakitori', 'Thịt gà xiên nướng', 'Grilled chicken skewer', 18, NOW());
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'わたしの [父]は かいしゃいんです。', '父', 'ちち', '"[\"ちち\", \"はは\", \"ふ\", \"おとう\"]"', 'Chữ 父 đứng một mình chỉ bố mình đọc là ちち.', 1, NOW()),
        (v_ch_id, 'READING', 'わたしの [母]は りょうりが じょうずです。', '母', 'はは', '"[\"はは\", \"ちち\", \"ぼ\", \"おかあ\"]"', 'Chữ 母 đứng một mình chỉ mẹ mình đọc là はは.', 2, NOW()),
        (v_ch_id, 'READING', '[子ども]たちが こうえんで あそんでいます。', '子ども', 'こども', '"[\"こども\", \"しども\", \"こじん\", \"こたち\"]"', '子ども (trẻ em) đọc là こども.', 3, NOW()),
        (v_ch_id, 'READING', 'あそこに [男の人]が います。', '男の人', 'おとこのひと', '"[\"おとこのひと\", \"なんのひと\", \"だんのひと\", \"おとこじん\"]"', '男の人 (người đàn ông) đọc là おとこのひと.', 4, NOW()),
        (v_ch_id, 'READING', '[女の子]が わらっています。', '女の子', 'おんなのこ', '"[\"おんなのこ\", \"じょのこ\", \"めすのこ\", \"おんなし\"]"', '女の子 (bé gái) đọc là おんなのこ.', 5, NOW()),
        (v_ch_id, 'READING', 'かわいい [子犬]を かっています。', '子犬', 'こいぬ', '"[\"こいぬ\", \"しいぬ\", \"こけん\", \"しょうけん\"]"', '子犬 (chó con) đọc là こいぬ.', 6, NOW()),
        (v_ch_id, 'READING', 'そらに [小鳥]が とんでいます。', '小鳥', 'ことり', '"[\"ことり\", \"しょうちょう\", \"こちょう\", \"ちいさいとり\"]"', '小鳥 (chim nhỏ) đọc là ことり.', 7, NOW()),
        (v_ch_id, 'READING', '[父母]に かんしゃの てがみを おくります。', '父母', 'ふぼ', '"[\"ふぼ\", \"ちちはは\", \"ふも\", \"ぶぼ\"]"', '父母 (bố mẹ) đọc âm On là ふぼ.', 8, NOW()),
        (v_ch_id, 'READING', '[男女]の なかよしグループです。', '男女', 'だんじょ', '"[\"だんじょ\", \"おとこおんな\", \"なんにょ\", \"だんにょ\"]"', '男女 (nam nữ) đọc là だんじょ.', 9, NOW()),
        (v_ch_id, 'READING', 'いざかやで [焼き鳥]を たべました。', '焼き鳥', 'やきとり', '"[\"やきとり\", \"やきちょう\", \"しょうちょう\", \"やきどり\"]"', '焼き鳥 (thịt gà nướng) đọc là やきとり.', 10, NOW()),
        (v_ch_id, 'WRITING', '[ちち]と キャッチボールを します。Kanji là:', 'ちち', '父', '"[\"父\", \"交\", \"文\", \"母\"]"', 'ちち (bố) viết chữ Hán là 父.', 1, NOW()),
        (v_ch_id, 'WRITING', '[はは]の えがおが だいすきです。Kanji là:', 'はは', '母', '"[\"母\", \"毎\", \"父\", \"女\"]"', 'はは (mẹ) viết chữ Hán là 母.', 2, NOW()),
        (v_ch_id, 'WRITING', '[こども]の ひに こいのぼりを かざります。Kanji là:', 'こども', '子ども', '"[\"子ども\", \"女子も\", \"小ども\", \"好ども\"]"', 'こども viết là 子ども.', 3, NOW()),
        (v_ch_id, 'WRITING', '[おとこのこ]が げんきに はしります。Kanji là:', 'おとこのこ', '男の子', '"[\"男の子\", \"田の子\", \"力の子\", \"勇の子\"]"', 'おとこのこ viết là 男の子.', 4, NOW()),
        (v_ch_id, 'WRITING', '[おんなのひと]が ピアノを ひきます。Kanji là:', 'おんなのひと', '女の人', '"[\"女の人\", \"好の人\", \"安の人\", \"如の人\"]"', 'おんなのひと viết là 女の人.', 5, NOW()),
        (v_ch_id, 'WRITING', '[いぬ]が しっぽを ふっています。Kanji là:', 'いぬ', '犬', '"[\"犬\", \"太\", \"大\", \"天\"]"', 'いぬ (chó) viết chữ Hán là 犬 (thêm dấu chấm trên chữ 大).', 6, NOW()),
        (v_ch_id, 'WRITING', '[とり]が えだに とまっています。Kanji là:', 'とり', '鳥', '"[\"鳥\", \"島\", \"烏\", \"鳴\"]"', 'とり (chim) viết chữ Hán là 鳥.', 7, NOW()),
        (v_ch_id, 'WRITING', '[ふぼ]を たいせつにします。Kanji là:', 'ふぼ', '父母', '"[\"父母\", \"母父\", \"父女\", \"父毎\"]"', 'ふぼ viết là 父母.', 8, NOW()),
        (v_ch_id, 'WRITING', '[だんじょ]びょうどうを まなびます。Kanji là:', 'だんじょ', '男女', '"[\"男女\", \"女男\", \"田女\", \"男子\"]"', 'だんじょ viết là 男女.', 9, NOW()),
        (v_ch_id, 'WRITING', '[ことり]に えさを あげます。Kanji là:', 'ことり', '小鳥', '"[\"小鳥\", \"少鳥\", \"子鳥\", \"細鳥\"]"', 'ことり (chim nhỏ) viết là 小鳥.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 えを みて かんじを かきましょう (Bức tranh công viên gia đình)', 'Quan sát bức tranh công viên trang 78, chọn chữ Hán chính xác điền vào 10 ô trống tương ứng vị trí 1 đến 10.', '/assets/kanji/n5/minigames/chap8_minigame_p78.webp', '"{\"example\": {\"prompt\": \"れい: Vị trí [れい] (Người bố dắt tay con)\", \"answer\": \"お [父] さん\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. Vị trí 1: お [ ? ] さん (Người mẹ dắt tay con đi chơi)\", \"options\": [\"母\", \"女\", \"父\", \"姉\"], \"answer\": \"母\", \"explanation\": \"Người mẹ là お母さん (おかあさん).\"}, {\"id\": 2, \"prompt\": \"2. Vị trí 2: [ ? ] ども (Em bé đi giữa bố và mẹ)\", \"options\": [\"子\", \"男\", \"女\", \"人\"], \"answer\": \"子\", \"explanation\": \"Đứa trẻ, con cái là 子ども (こども).\"}, {\"id\": 3, \"prompt\": \"3. Vị trí 3: [ ? ] の人 (Người đàn ông ngồi đọc báo trên ghế đá)\", \"options\": [\"男\", \"女\", \"父\", \"子\"], \"answer\": \"男\", \"explanation\": \"Người đàn ông là 男の人 (おとこのひと).\"}, {\"id\": 4, \"prompt\": \"4. Vị trí 4: [ ? ] の人 (Người phụ nữ mặc váy xách túi đi vào công viên)\", \"options\": [\"女\", \"母\", \"男\", \"子\"], \"answer\": \"女\", \"explanation\": \"Người phụ nữ là 女の人 (おんなのひと).\"}, {\"id\": 5, \"prompt\": \"5. Vị trí 5: 男の [ ? ] (Bé trai chạy tung tăng trên sân)\", \"options\": [\"子\", \"人\", \"生\", \"児\"], \"answer\": \"子\", \"explanation\": \"Bé trai là 男の子 (おとこのこ).\"}, {\"id\": 6, \"prompt\": \"6. Vị trí 6: 女の [ ? ] (Bé gái đang ngồi xúc cát)\", \"options\": [\"子\", \"人\", \"生\", \"児\"], \"answer\": \"子\", \"explanation\": \"Bé gái là 女の子 (おんなのこ).\"}, {\"id\": 7, \"prompt\": \"7. Vị trí 7: [ ? ] 学生 (Nam sinh trung học nắm tay bạn gái)\", \"options\": [\"男子\", \"男\", \"大学生\", \"先生\"], \"answer\": \"男子\", \"explanation\": \"Nam sinh viên/học sinh là 男子学生 (だんしがくせい).\"}, {\"id\": 8, \"prompt\": \"8. Vị trí 8: [ ? ] 学生 (Nữ sinh trung học nắm tay bạn trai)\", \"options\": [\"女子\", \"女\", \"高校生\", \"生徒\"], \"answer\": \"女子\", \"explanation\": \"Nữ sinh viên/học sinh là 女子学生 (じょしがくせい).\"}, {\"id\": 9, \"prompt\": \"9. Vị trí 9: [ ? ] (Chú chó chạy nô đùa bên cạnh bãi cát)\", \"options\": [\"犬\", \"鳥\", \"猫\", \"牛\"], \"answer\": \"犬\", \"explanation\": \"Con chó viết là 犬 (いぬ).\"}, {\"id\": 10, \"prompt\": \"10. Vị trí 10: [ ? ] (Hai chú chim bồ câu đậu trên cành cây)\", \"options\": [\"鳥\", \"犬\", \"魚\", \"花\"], \"answer\": \"鳥\", \"explanation\": \"Con chim viết là 鳥 (とり).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 えから できた かんじ (Hình vẽ tượng hình ra chữ Hán)', 'Quan sát hình vẽ tượng hình thời cổ đại ở trang 79 và chọn chữ Hán tương ứng (5 câu).', '/assets/kanji/n5/minigames/chap8_minigame_p79.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"1. Hình hai bàn tay cầm chiếc rìu đá chỉ quyền uy của người cha trong gia đình:\", \"options\": [\"父\", \"手\", \"石\", \"木\"], \"answer\": \"父\", \"explanation\": \"Chữ 父 (Phụ - cha) bắt nguồn từ hình bàn tay cầm rìu đá quyền uy.\"}, {\"id\": 2, \"prompt\": \"2. Hình em bé sơ sinh quấn tã đang dang hai tay chào đời:\", \"options\": [\"子\", \"人\", \"生\", \"大\"], \"answer\": \"子\", \"explanation\": \"Chữ 子 (Tử - con trẻ) bắt nguồn từ hình dáng em bé sơ sinh.\"}, {\"id\": 3, \"prompt\": \"3. Hình thiếu nữ mặc áo kimono quý phái khoanh tay duyên dáng:\", \"options\": [\"女\", \"母\", \"安\", \"好\"], \"answer\": \"女\", \"explanation\": \"Chữ 女 (Nữ - phụ nữ) tượng hình người phụ nữ khoanh tay trước ngực.\"}, {\"id\": 4, \"prompt\": \"4. Hình người mẹ quỳ gối ôm ngực cho con thơ bú mớm tình mẫu tử:\", \"options\": [\"母\", \"女\", \"毎\", \"乳\"], \"answer\": \"母\", \"explanation\": \"Chữ 母 (Mẫu - người mẹ) bắt nguồn từ hình ảnh người mẹ quỳ cho con bú có 2 nét chấm tượng trưng hai bầu sữa.\"}, {\"id\": 5, \"prompt\": \"5. Hình thửa ruộng (田) cộng với sức bắp tay cơ bắp (力) làm việc cày cấy:\", \"options\": [\"男\", \"力\", \"田\", \"勇\"], \"answer\": \"男\", \"explanation\": \"Điền 田 kết hợp với Lực 力 tạo thành chữ 男 (Nam - người đàn ông trụ cột).\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 わたしの かぞく (Đoạn văn ''Gia đình của tôi'')', 'Đọc bài văn tự sự giới thiệu gia đình ở trang 79, chọn chữ Hán đúng cho đầy đủ 13 vị trí từ ① đến ⑬.', '/assets/kanji/n5/minigames/chap8_minigame_p79.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① わたしは [ごにん] かぞくです (Gia đình có 5 người)\", \"options\": [\"五人\", \"四人\", \"三人\", \"六人\"], \"answer\": \"五人\", \"explanation\": \"ごにん viết là 五人 (5 người).\"}, {\"id\": 2, \"prompt\": \"② [そふ] と ちちと ははと いぬの ポチです (Ông nội)\", \"options\": [\"そ父\", \"父\", \"祖父\", \"祖母\"], \"answer\": \"そ父\", \"explanation\": \"そふ viết chữ Hán trong bài là そ父 (ông nội).\"}, {\"id\": 3, \"prompt\": \"③ そふと [ちち] と ははと...\", \"options\": [\"父\", \"母\", \"兄\", \"弟\"], \"answer\": \"父\", \"explanation\": \"ちち viết là 父 (bố).\"}, {\"id\": 4, \"prompt\": \"④ そふと ちちと [はは] と...\", \"options\": [\"母\", \"女\", \"姉\", \"妹\"], \"answer\": \"母\", \"explanation\": \"はは viết là 母 (mẹ).\"}, {\"id\": 5, \"prompt\": \"⑤ [いぬ] の ポチです (Chú chó Pochi)\", \"options\": [\"犬\", \"鳥\", \"猫\", \"子\"], \"answer\": \"犬\", \"explanation\": \"いぬ viết là 犬 (chó).\"}, {\"id\": 6, \"prompt\": \"⑥ そふは [ななじゅうろくさい] ですが とても げんきです\", \"options\": [\"七十六さい\", \"六十七さい\", \"七十さい\", \"八十六さい\"], \"answer\": \"七十六さい\", \"explanation\": \"ななじゅうろくさい viết là 七十六さい (76 tuổi).\"}, {\"id\": 7, \"prompt\": \"⑦ ちちは [よんじゅうはっさい] です\", \"options\": [\"四十八さい\", \"八十四さい\", \"四十さい\", \"四十五さい\"], \"answer\": \"四十八さい\", \"explanation\": \"よんじゅうはっさい viết là 四十八さい (48 tuổi).\"}, {\"id\": 8, \"prompt\": \"⑧ [しょうがっこう] の せんせいです\", \"options\": [\"小学校\", \"中学校\", \"高校\", \"大学\"], \"answer\": \"小学校\", \"explanation\": \"しょうがっこう viết là 小学校 (trường tiểu học).\"}, {\"id\": 9, \"prompt\": \"⑨ しょうがっこうの [せんせい] です\", \"options\": [\"先生\", \"学生\", \"校長\", \"教員\"], \"answer\": \"先生\", \"explanation\": \"せんせい viết là 先生 (giáo viên).\"}, {\"id\": 10, \"prompt\": \"⑩ ははは [こうこう] の せんせいです\", \"options\": [\"高校\", \"大学\", \"小学校\", \"学校\"], \"answer\": \"高校\", \"explanation\": \"こうこう viết là 高校 (trường cấp 3).\"}, {\"id\": 11, \"prompt\": \"⑪ ポチは [2ねんまえ] うちへ きました\", \"options\": [\"2年まえ\", \"1年まえ\", \"3年まえ\", \"去年\"], \"answer\": \"2年まえ\", \"explanation\": \"2ねんまえ viết là 2年まえ (2 năm trước).\"}, {\"id\": 12, \"prompt\": \"⑫ わたしは [まいにち] ポチと かわへ さんぽに いきます\", \"options\": [\"まい日\", \"毎日\", \"休日\", \"今日\"], \"answer\": \"まい日\", \"explanation\": \"まいにち viết là まい日 (mỗi ngày).\"}, {\"id\": 13, \"prompt\": \"⑬ わたしは まいにち ポチと [かわ] へ さんぽに いきます\", \"options\": [\"川\", \"山\", \"海\", \"田\"], \"answer\": \"川\", \"explanation\": \"かわ viết là 川 (dòng sông).\"}]}"', 3, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
