        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'せきから [立って]ください。', '立って', 'たって', '"[\"たって\", \"すわって\", \"やすんで\", \"いって\"]"', '立って (hãy đứng lên) đọc là たって.', 1, NOW()),
        (v_ch_id, 'READING', 'きょうは かいしゃの [休み]です。', '休み', 'やすみ', '"[\"やすみ\", \"きゅうみ\", \"たてみ\", \"みずみ\"]"', '休み (ngày nghỉ) đọc là やすみ.', 2, NOW()),
        (v_ch_id, 'READING', 'えいがを [見ます]。', '見ます', 'みます', '"[\"みます\", \"ききます\", \"いきます\", \"かえります\"]"', '見ます (xem phim) đọc là みます.', 3, NOW()),
        (v_ch_id, 'READING', 'おんがくを [聞きます]。', '聞きます', 'ききます', '"[\"ききます\", \"みます\", \"いいます\", \"かきます\"]"', '聞きます (nghe nhạc) đọc là ききます.', 4, NOW()),
        (v_ch_id, 'READING', 'あした とうきょうへ [行きます]。', '行きます', 'いきます', '"[\"いきます\", \"きます\", \"かえります\", \"おります\"]"', '行きます (đi Tokyo) đọc là いきます.', 5, NOW()),
        (v_ch_id, 'READING', 'ともだちが うちへ [来ます]。', '来ます', 'きます', '"[\"きます\", \"いきます\", \"かえります\", \"みます\"]"', '来ます (đến nhà) đọc là きます.', 6, NOW()),
        (v_ch_id, 'READING', 'ろくじに うちへ [帰ります]。', '帰ります', 'かえります', '"[\"かえります\", \"いきます\", \"きます\", \"やすみます\"]"', '帰ります (về nhà) đọc là かえります.', 7, NOW()),
        (v_ch_id, 'READING', '[休日]は なにを しますか。', '休日', 'きゅうじつ', '"[\"きゅうじつ\", \"やすみひ\", \"きゅうひ\", \"やすみび\"]"', '休日 (ngày nghỉ) đọc là きゅうじつ.', 8, NOW()),
        (v_ch_id, 'READING', '[来年] にほんへ りゅうがくします。', '来年', 'らいねん', '"[\"らいねん\", \"きねん\", \"こねん\", \"まいねん\"]"', '来年 (năm sau) đọc là らいねん.', 9, NOW()),
        (v_ch_id, 'READING', 'こうじょうの [見学]を しました。', '見学', 'けんがく', '"[\"けんがく\", \"みかく\", \"みまなび\", \"けんこう\"]"', '見学 (tham quan kiến tập) đọc là けんがく.', 10, NOW()),
        (v_ch_id, 'WRITING', 'きりつのごうれいで [た]ちます。Kanji là:', 'た', '立', '"[\"立\", \"休\", \"位\", \"音\"]"', 'たつ (đứng lên) viết là 立つ.', 1, NOW()),
        (v_ch_id, 'WRITING', 'ベッドで ゆっくり [やす]みます。Kanji là:', 'やす', '休', '"[\"休\", \"体\", \"木\", \"本\"]"', 'やすむ (nghỉ ngơi) viết là 休む.', 2, NOW()),
        (v_ch_id, 'WRITING', 'アニメを [み]るのが すきです。Kanji là:', 'み', '見', '"[\"見\", \"貝\", \"目\", \"観\"]"', 'みる (xem, nhìn) viết là 見る.', 3, NOW()),
        (v_ch_id, 'WRITING', 'ラジオの ニュースを [き]きます。Kanji là:', 'き', '聞', '"[\"聞\", \"間\", \"門\", \"問\"]"', 'きく (nghe) viết là 聞く (chữ 耳 bên trong chữ 門).', 4, NOW()),
        (v_ch_id, 'WRITING', 'きょうとへ [い]きます。Kanji là:', 'い', '行', '"[\"行\", \"来\", \"走\", \"待\"]"', 'いく (đi) viết là 行く.', 5, NOW()),
        (v_ch_id, 'WRITING', 'あした せんせいが [き]ます。Kanji là:', 'き', '来', '"[\"来\", \"行\", \"未\", \"東\"]"', 'くる (đến) viết là 来る.', 6, NOW()),
        (v_ch_id, 'WRITING', 'くにへ [かえ]りたいです。Kanji là:', 'かえ', '帰', '"[\"帰\", \"反\", \"返\", \"復\"]"', 'かえる (trở về) viết là 帰る.', 7, NOW()),
        (v_ch_id, 'WRITING', '[きゅうじつ]にしゅっきんします。Kanji là:', 'きゅうじつ', '休日', '"[\"休日\", \"体日\", \"休月\", \"木日\"]"', 'きゅうじつ viết là 休日.', 8, NOW()),
        (v_ch_id, 'WRITING', '[らいげつ] はじめて にほんへ いきます。Kanji là:', 'らいげつ', '来月', '"[\"来月\", \"去月\", \"毎月\", \"今月\"]"', 'らいげつ viết là 来月.', 9, NOW()),
        (v_ch_id, 'WRITING', 'らいしゅう [きこく]します。Kanji là:', 'きこく', '帰国', '"[\"帰国\", \"去国\", \"返国\", \"入国\"]"', 'きこく (về nước) viết là 帰国.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 どうしを えらびましょう (Chọn động từ thích hợp vào câu)', 'Chọn động từ thích hợp từ khung cho sẵn (立, 行, 見, 休, 来, 聞, 帰) điền vào 6 câu hỏi trang 86.', '/assets/kanji/n5/minigames/chap9_minigame_p86.webp', '"{\"example\": {\"prompt\": \"れい: [ 立 ] ってください (た)\", \"answer\": \"立\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. CDを [ ? ] きます。(Cách đọc: き)\", \"options\": [\"聞\", \"見\", \"行\", \"来\"], \"answer\": \"聞\", \"explanation\": \"Nghe CD dùng chữ 聞: 聞きます (ききます).\"}, {\"id\": 2, \"prompt\": \"2. アニメを [ ? ] ます。(Cách đọc: み)\", \"options\": [\"見\", \"聞\", \"行\", \"休\"], \"answer\": \"見\", \"explanation\": \"Xem anime dùng chữ 見: 見ます (みます).\"}, {\"id\": 3, \"prompt\": \"3. 日本へ [ ? ] ました。(Cách đọc: き)\", \"options\": [\"来\", \"行\", \"帰\", \"立\"], \"answer\": \"来\", \"explanation\": \"Đến Nhật Bản dùng chữ 来: 来ました (きました).\"}, {\"id\": 4, \"prompt\": \"4. えいがかんへ [ ? ] きませんか。(Cách đọc: い)\", \"options\": [\"行\", \"来\", \"帰\", \"見\"], \"answer\": \"行\", \"explanation\": \"Đi rạp chiếu phim dùng chữ 行: 行きませんか (いきませんか).\"}, {\"id\": 5, \"prompt\": \"5. うちへ [ ? ] ります。(Cách đọc: かえ)\", \"options\": [\"帰\", \"行\", \"来\", \"休\"], \"answer\": \"帰\", \"explanation\": \"Về nhà dùng chữ 帰: 帰ります (かえります).\"}, {\"id\": 6, \"prompt\": \"6. つかれましたね。すこし [ ? ] みませんか。(Cách đọc: やす)\", \"options\": [\"休\", \"見\", \"立\", \"帰\"], \"answer\": \"休\", \"explanation\": \"Nghỉ ngơi dùng chữ 休: 休みませんか (やすみませんか).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 タイムスケジュール (Lịch trình sinh hoạt của 3 người bạn)', 'Quan sát bảng thời gian biểu của Jake, Marin và You ở trang 87 để xác định ai làm hành động gì (5 câu).', '/assets/kanji/n5/minigames/chap9_minigame_p87.webp', '"{\"example\": {\"prompt\": \"れい: あさ しん聞を よみます (7:00 しんぶん)\", \"answer\": \"マリンさん\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. まい日 6じ (18:00) に うちへ 帰ります (かえります):\", \"options\": [\"ジェイクさん\", \"マリンさん\", \"ヨウさん\", \"だれでもない\"], \"answer\": \"ジェイクさん\", \"explanation\": \"Thời gian biểu của Jake ghi: 18:00 うちへ かえります.\"}, {\"id\": 2, \"prompt\": \"2. あさ (9:00) アルバイトに 行きます (いきます):\", \"options\": [\"マリンさん\", \"ジェイクさん\", \"ヨウさん\", \"三人とも\"], \"answer\": \"マリンさん\", \"explanation\": \"Thời gian biểu của Marin ghi: 9:00 アルバイトへ いきます.\"}, {\"id\": 3, \"prompt\": \"3. テレビを 見ます (20:00)。それから シャワーを あびます (22:00):\", \"options\": [\"ジェイクさん\", \"マリンさん\", \"ヨウさん\", \"だれでもない\"], \"answer\": \"ジェイクさん\", \"explanation\": \"Jake ghi: 20:00 テレビをみます, 22:00 シャワーをあびます.\"}, {\"id\": 4, \"prompt\": \"4. うちで おんがくを 聞きます (18:00 ききます):\", \"options\": [\"ヨウさん\", \"ジェイクさん\", \"マリンさん\", \"二人\"], \"answer\": \"ヨウさん\", \"explanation\": \"Thời gian biểu của You ghi: 18:00 おんがくを ききます.\"}, {\"id\": 5, \"prompt\": \"5. ごご 1じ (13:00) に 学校へ 行きます (がっこうへ いきます):\", \"options\": [\"マリンさん\", \"ヨウさん\", \"ジェイクさん\", \"三人とも\"], \"answer\": \"マリンさん\", \"explanation\": \"Thời gian biểu của Marin ghi: 13:00 がっこうへ いきます.\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 かんじの けいさんです (Phép tính Kanji)', 'Ghép các bộ thủ được cộng lại thành chữ Hán tương ứng (đầy đủ 3 câu ở trang 87).', '/assets/kanji/n5/minigames/chap9_minigame_p87.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"1. 刂 + ⺕ + 帀 = [ ? ]\", \"options\": [\"帰\", \"聞\", \"立\", \"行\"], \"answer\": \"帰\", \"explanation\": \"Bộ Đao bên phải + bộ Sơn lật ⺕ + bộ Bố 帀 tạo thành chữ 帰 (QUY - trở về).\"}, {\"id\": 2, \"prompt\": \"2. 門 + 耳 = [ ? ]\", \"options\": [\"聞\", \"間\", \"開\", \"問\"], \"answer\": \"聞\", \"explanation\": \"Bộ Môn 門 bên ngoài ghé tai 耳 vào nghe tạo thành chữ 聞 (VĂN - nghe, hỏi).\"}, {\"id\": 3, \"prompt\": \"3. 亠 + 丷 + 一 = [ ? ]\", \"options\": [\"立\", \"音\", \"辛\", \"文\"], \"answer\": \"立\", \"explanation\": \"Bộ Đầu 亠 + nét phẩy chấm 丷 + nét ngang 一 tạo thành chữ 立 (LẬP - đứng).\"}]}"', 3, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
