        (v_ch_id, '飲み物', 'のみもの', 'nomimono', 'Đồ uống', 'Drink, beverage', 17, NOW()),
        (v_ch_id, '買い物', 'かいもの', 'kaimono', 'Mua sắm', 'Shopping', 18, NOW());
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'にほんの [お米]は とても おいしいです。', 'お米', 'おこめ', '"[\"おこめ\", \"おまい\", \"おべい\", \"おこ\"]"', 'お米 (hạt gạo) đọc là おこめ.', 1, NOW()),
        (v_ch_id, 'READING', 'しょくごに あたたかい [お茶]を のみます。', 'お茶', 'おちゃ', '"[\"おちゃ\", \"おさ\", \"おてぃ\", \"おちゃいろ\"]"', 'お茶 (trà) đọc là おちゃ.', 2, NOW()),
        (v_ch_id, 'READING', 'まいあさ [牛乳]を いっぱいのんでいます。', '牛乳', 'ぎゅうにゅう', '"[\"ぎゅうにゅう\", \"うしちち\", \"ぎゅうにゅ\", \"うしにゅう\"]"', '牛乳 (sữa tươi) đọc là ぎゅうにゅう.', 3, NOW()),
        (v_ch_id, 'READING', 'スーパーで [牛肉]を かいました。', '牛肉', 'ぎゅうにく', '"[\"ぎゅうにく\", \"うしにく\", \"ぎゅうじし\", \"うしじし\"]"', '牛肉 (thịt bò) đọc là ぎゅうにく.', 4, NOW()),
        (v_ch_id, 'READING', 'いけで [魚]が およいでいます。', '魚', 'さかな', '"[\"さかな\", \"ぎょ\", \"うお\", \"ざかな\"]"', '魚 (con cá) đọc âm Kun là さかな.', 5, NOW()),
        (v_ch_id, 'READING', 'かいがんで きれいな [貝]を ひろいました。', '貝', 'かい', '"[\"かい\", \"ばい\", \"がい\", \"こ\"]"', '貝 (con sò) đọc là かい.', 6, NOW()),
        (v_ch_id, 'READING', 'にほんりょうりが [大好き]です。', '大好き', 'だいすき', '"[\"だいすき\", \"たいすき\", \"おおすき\", \"だいこう\"]"', '大好き (rất thích) đọc là だいすき.', 7, NOW()),
        (v_ch_id, 'READING', 'おいしい [食べ物]を たくさん たべました。', '食べ物', 'たべもの', '"[\"たべもの\", \"しょくぶつ\", \"たべぶつ\", \"しょくもの\"]"', '食べ物 (thức ăn) đọc là たべもの.', 8, NOW()),
        (v_ch_id, 'READING', 'つめたい [飲み物]を ください。', '飲み物', 'のみもの', '"[\"のみもの\", \"いんぶつ\", \"のみぶつ\", \"いんもの\"]"', '飲み物 (thức uống) đọc là のみもの.', 9, NOW()),
        (v_ch_id, 'READING', 'しゅうまつに デパートへ [買い物]に いきます。', '買い物', 'かいもの', '"[\"かいもの\", \"ばいぶつ\", \"かいぶつ\", \"ばいもの\"]"', '買い物 (mua sắm) đọc là かいもの.', 10, NOW()),
        (v_ch_id, 'WRITING', 'すいはんきで [こめ]を たきます。Kanji là:', 'こめ', '米', '"[\"米\", \"茶\", \"来\", \"木\"]"', 'こめ (gạo) viết chữ Hán là 米.', 1, NOW()),
        (v_ch_id, 'WRITING', 'きっさてんで [おちゃ]を のみます。Kanji là:', 'おちゃ', 'お茶', '"[\"お茶\", \"お米\", \"お草\", \"お菓\"]"', 'おちゃ (trà) viết là お茶.', 2, NOW()),
        (v_ch_id, 'WRITING', 'すきやきには [ぎゅうにく]を つかいます。Kanji là:', 'ぎゅうにく', '牛肉', '"[\"牛肉\", \"牛内\", \"生肉\", \"午肉\"]"', 'ぎゅうにく viết là 牛肉.', 3, NOW()),
        (v_ch_id, 'WRITING', 'かわずしで [さかな]の すしを たべます。Kanji là:', 'さかな', '魚', '"[\"魚\", \"鳥\", \"貝\", \"漁\"]"', 'さかな (cá) viết chữ Hán là 魚.', 4, NOW()),
        (v_ch_id, 'WRITING', 'みそしるに [かい]を いれます。Kanji là:', 'かい', '貝', '"[\"貝\", \"見\", \"目\", \"具\"]"', 'かい (con sò) viết chữ Hán là 貝.', 5, NOW()),
        (v_ch_id, 'WRITING', 'わたしは りんごが [す]きです。Kanji là:', 'す', '好', '"[\"好\", \"安\", \"如\", \"妹\"]"', 'すき (thích) viết chữ Hán là 好き.', 6, NOW()),
        (v_ch_id, 'WRITING', 'にほんの [たべもの]は からだに いいです。Kanji là:', 'たべもの', '食べ物', '"[\"食べ物\", \"食へ物\", \"飲物\", \"喰物\"]"', 'たべもの viết là 食べ物.', 7, NOW()),
        (v_ch_id, 'WRITING', 'じどうはんばいきで [のみもの]を かいます。Kanji là:', 'のみもの', '飲み物', '"[\"飲み物\", \"飲物\", \"喫み物\", \"喰み物\"]"', 'のみもの viết là 飲み物.', 8, NOW()),
        (v_ch_id, 'WRITING', 'あした [かいもの]に いきます。Kanji là:', 'かいもの', '買い物', '"[\"買い物\", \"買物\", \"換い物\", \"貸い物\"]"', 'かいもの viết là 買い物.', 9, NOW()),
        (v_ch_id, 'WRITING', 'わたしの [こうぶつ]は ラーメンです。Kanji là:', 'こうぶつ', '好物', '"[\"好物\", \"愛物\", \"快物\", \"楽物\"]"', 'こうぶつ (món khoái khẩu) viết là 好物.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 かんじの まちがいさがし (Tìm lỗi sai trong chữ Hán)', 'Quan sát tranh thức ăn và sửa lại các chữ Hán bị viết sai nét thành chữ đúng (5 câu trang 94).', '/assets/kanji/n5/minigames/chap10_minigame_p94.webp', '"{\"example\": {\"prompt\": \"れい: Tranh con bò vẽ chữ 午 -> sửa thành:\", \"answer\": \"牛\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. Tranh con cá vẽ chữ viết thiếu nét ở phần đuôi -> sửa thành:\", \"options\": [\"魚\", \"鳥\", \"貝\", \"角\"], \"answer\": \"魚\", \"explanation\": \"Chữ con cá đúng là 魚 (NGƯ - さかな).\"}, {\"id\": 2, \"prompt\": \"2. Tranh con sò viết nhầm thành chữ 見 -> sửa thành:\", \"options\": [\"貝\", \"見\", \"目\", \"頁\"], \"answer\": \"貝\", \"explanation\": \"Chữ con sò là 貝 (BỐI - かい), phần dưới là 2 nét phẩy chấm 八 thay vì 儿.\"}, {\"id\": 3, \"prompt\": \"3. Tranh bát cơm trắng viết nhầm thành chữ 采 -> sửa thành:\", \"options\": [\"米\", \"采\", \"木\", \"来\"], \"answer\": \"米\", \"explanation\": \"Chữ hạt gạo, cơm là 米 (MỄ - こめ).\"}, {\"id\": 4, \"prompt\": \"4. Tranh ấm trà xanh viết nhầm thành chữ 筡 -> sửa thành:\", \"options\": [\"茶\", \"草\", \"葉\", \"菜\"], \"answer\": \"茶\", \"explanation\": \"Chữ trà là 茶 (TRÀ - おちゃ).\"}, {\"id\": 5, \"prompt\": \"5. Tranh miếng thịt bò viết nhầm thành chữ 内 -> sửa thành:\", \"options\": [\"肉\", \"内\", \"円\", \"用\"], \"answer\": \"肉\", \"explanation\": \"Chữ miếng thịt là 肉 (NHỤC - にく), bên trong có 2 chữ 人.\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 だれの 子どもですか (Đứa bé là con của ai?)', 'Đọc lời thoại giới thiệu sở thích ăn uống của các phụ huynh trang 95 để ghép với 4 đứa trẻ trong tranh.', '/assets/kanji/n5/minigames/chap10_minigame_p95.webp', '"{\"example\": {\"prompt\": \"れい: Bé gái tóc đuôi ngựa thích ăn thịt (肉)\", \"answer\": \"石田さん (いしださん)\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. Bé gái buộc 2 bím tóc, thích uống trà xanh (お茶):\", \"options\": [\"山川さん\", \"石川さん\", \"山田さん\", \"田中さん\"], \"answer\": \"山川さん\", \"explanation\": \"Lời thoại Yamakawa: わたしの 子どもは 女の子です。お茶が 好きです。\"}, {\"id\": 2, \"prompt\": \"2. Bé trai đầu đinh, thích ăn sò biển (貝):\", \"options\": [\"石川さん\", \"田中さん\", \"山田さん\", \"竹中さん\"], \"answer\": \"石川さん\", \"explanation\": \"Lời thoại Ishikawa: わたしの 子どもは 男の子です。貝が 好きです。\"}, {\"id\": 3, \"prompt\": \"3. Bé gái tóc ngắn uốn, thích ăn cá (魚):\", \"options\": [\"山田さん\", \"山川さん\", \"石田さん\", \"田中さん\"], \"answer\": \"山田さん\", \"explanation\": \"Lời thoại Yamada: わたしの 子どもは 女の子です。魚が 好きです。\"}, {\"id\": 4, \"prompt\": \"4. Bé trai tóc vuốt lệch, thích ăn thịt (肉):\", \"options\": [\"田中さん\", \"竹中さん\", \"石川さん\", \"山川さん\"], \"answer\": \"田中さん\", \"explanation\": \"Lời thoại Tanaka: わたしの 子どもは 男の子です。肉が 好きです。\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 よみましょう。そして こたえましょう (Đọc câu hỏi sở thích)', 'Đọc các câu hỏi hội thoại về món ăn và động vật yêu thích ở bài 【3】 trang 95, điền cách đọc đúng cho 7 vị trí ① đến ⑦.', '/assets/kanji/n5/minigames/chap10_minigame_p95.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① A: [すき] な たべ物は なんですか\", \"options\": [\"すき\", \"たのし\", \"うれし\", \"よ\"], \"answer\": \"すき\", \"explanation\": \"好きな đọc là すきな (thích).\"}, {\"id\": 2, \"prompt\": \"② A: 好きな [たべもの] は なんですか\", \"options\": [\"たべもの\", \"のみもの\", \"かいもの\", \"くだもの\"], \"answer\": \"たべもの\", \"explanation\": \"食べ物 đọc là たべもの (đồ ăn, món ăn).\"}, {\"id\": 3, \"prompt\": \"③ A: [にく] と 魚と どちらが 好きですか\", \"options\": [\"にく\", \"うし\", \"とり\", \"ぶた\"], \"answer\": \"にく\", \"explanation\": \"肉 đọc là にく (thịt).\"}, {\"id\": 4, \"prompt\": \"④ A: 肉と [さかな] と どちらが 好きですか\", \"options\": [\"さかな\", \"かい\", \"うお\", \"えび\"], \"answer\": \"さかな\", \"explanation\": \"魚 đọc là さかな (cá).\"}, {\"id\": 5, \"prompt\": \"⑤ A: 肉と 魚と どちらが [すき] ですか\", \"options\": [\"すき\", \"きらい\", \"いい\", \"たか\"], \"answer\": \"すき\", \"explanation\": \"好き đọc là すき (thích hơn).\"}, {\"id\": 6, \"prompt\": \"⑥ A: [すき] な どう物は なんですか\", \"options\": [\"すき\", \"たのし\", \"おお\", \"ちい\"], \"answer\": \"すき\", \"explanation\": \"好きな đọc là すきな (yêu thích).\"}, {\"id\": 7, \"prompt\": \"⑦ A: 好きな [どうぶつ] は なんですか\", \"options\": [\"どうぶつ\", \"せいぶつ\", \"たべもの\", \"とり\"], \"answer\": \"どうぶつ\", \"explanation\": \"動物 đọc là どうぶつ (động vật).\"}]}"', 3, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
