        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'やまの [小林]を あるきます。', '小林', 'こばやし', '"[\"こばやし\", \"しょうりん\", \"おばやし\", \"ちいさいもり\"]"', '小林 (rừng thưa nhỏ) đọc là こばやし.', 1, NOW()),
        (v_ch_id, 'READING', 'ふかい [森]に どうぶつが います。', '森', 'もり', '"[\"もり\", \"はやし\", \"しん\", \"やま\"]"', '森 (rừng rậm bạt ngàn) đọc là もり.', 2, NOW()),
        (v_ch_id, 'READING', 'そふは [畑]で やさいを つくります。', '畑', 'はたけ', '"[\"はたけ\", \"たけ\", \"た\", \"ばたけ\"]"', '畑 (ruộng khô trồng rau) đọc là はたけ.', 3, NOW()),
        (v_ch_id, 'READING', 'おおきな [岩]が あります。', '岩', 'いわ', '"[\"いわ\", \"いし\", \"がん\", \"すな\"]"', '岩 (tảng đá to) đọc là いわ.', 4, NOW()),
        (v_ch_id, 'READING', 'きれいな [音楽]が きこえます。', '音楽', 'おんがく', '"[\"おんがく\", \"おとらく\", \"おんらく\", \"ねがく\"]"', '音楽 (âm nhạc) đọc là おんがく.', 5, NOW()),
        (v_ch_id, 'READING', 'このへやは [明るい]です。', '明るい', 'あかるい', '"[\"あかるい\", \"めいるい\", \"あかる\", \"ひろい\"]"', '明るい (sáng sủa) đọc là あかるい.', 6, NOW()),
        (v_ch_id, 'READING', 'そとが [暗く]なりました。', '暗く', 'くらく', '"[\"くらく\", \"あかく\", \"あかるく\", \"くろく\"]"', '暗く (trở nên tối tăm) đọc là くらく.', 7, NOW()),
        (v_ch_id, 'READING', '[森林]を たいせつに まもります。', '森林', 'しんりん', '"[\"しんりん\", \"もりはやし\", \"しんり\", \"もりばやし\"]"', '森林 (rừng sâu rừng rậm) đọc là しんりん.', 8, NOW()),
        (v_ch_id, 'READING', '[明日の] よていを かくにんします。', '明日の', 'あしたの', '"[\"あしたの\", \"あすの\", \"みょうにちの\", \"あかるいの\"]"', '明日 (ngày mai) đọc là あした.', 9, NOW()),
        (v_ch_id, 'READING', 'にほんごの [発音]を れんしゅうします。', '発音', 'はつおん', '"[\"はつおん\", \"はつおと\", \"はつね\", \"ほつおん\"]"', '発音 (phát âm) chữ 音 đọc là おん (はつおん).', 10, NOW()),
        (v_ch_id, 'WRITING', '[はやし]の なかで とりのこえを ききます。Kanji là:', 'はやし', '林', '"[\"林\", \"森\", \"木\", \"枝\"]"', 'はやし (rừng thưa) gồm hai chữ 木: chữ 林.', 1, NOW()),
        (v_ch_id, 'WRITING', '[もり]の なかは すずしいです。Kanji là:', 'もり', '森', '"[\"森\", \"林\", \"木\", \"葉\"]"', 'もり (rừng rậm) gồm ba chữ 木: chữ 森.', 2, NOW()),
        (v_ch_id, 'WRITING', '[はたけ]で トマトを そだてます。Kanji là:', 'はたけ', '畑', '"[\"畑\", \"田\", \"火\", \"草\"]"', 'はたけ (ruộng hoa màu) chữ Hán là 畑.', 3, NOW()),
        (v_ch_id, 'WRITING', '[いわ]の うえで やすみます。Kanji là:', 'いわ', '岩', '"[\"岩\", \"石\", \"山\", \"岸\"]"', 'いわ (tảng đá lớn) chữ Hán là 岩.', 4, NOW()),
        (v_ch_id, 'WRITING', 'ラジオの [おと]が ちいさいです。Kanji là:', 'おと', '音', '"[\"音\", \"暗\", \"日\", \"立\"]"', 'おと (âm thanh) chữ Hán là 音.', 5, NOW()),
        (v_ch_id, 'WRITING', 'でんきをつけて [あか]るくします。Kanji là:', 'あか', '明', '"[\"明\", \"暗\", \"日\", \"光\"]"', 'あかるい (sáng sủa) chữ Hán là 明るい.', 6, NOW()),
        (v_ch_id, 'WRITING', 'よるは みちが [くら]いです。Kanji là:', 'くら', '暗', '"[\"暗\", \"明\", \"黒\", \"夜\"]"', 'くらい (tối tăm) chữ Hán là 暗い.', 7, NOW()),
        (v_ch_id, 'WRITING', '[おんがく]を きくのが しゅみです。Kanji là:', 'おんがく', '音楽', '"[\"音楽\", \"音学\", \"暗楽\", \"声楽\"]"', 'おんがく (âm nhạc) viết là 音楽.', 8, NOW()),
        (v_ch_id, 'WRITING', '[あした]の あさはやい です。Kanji là:', 'あした', '明日', '"[\"明日\", \"明後日\", \"昨日\", \"今日\"]"', 'あした viết chữ Hán là 明日.', 9, NOW()),
        (v_ch_id, 'WRITING', '[はなばたけ]へ ドライブに いきます。Kanji là:', 'はなばたけ', '花畑', '"[\"花畑\", \"華畑\", \"花田\", \"華田\"]"', 'はなばたけ (vườn hoa) viết là 花畑.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 えを 見て、かんじを かきましょう (Nhìn tranh đoán chữ Hán ghép)', 'Quan sát các bức tranh thiên nhiên trang 104 và viết chữ Hán tương ứng (5 câu).', '/assets/kanji/n5/minigames/chap11_minigame_p104.webp', '"{\"example\": {\"prompt\": \"れい: Tranh người mẹ ôm con gái\", \"answer\": \"好\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. Ba cái cây đứng cạnh nhau tạo thành cánh rừng rậm rạp:\", \"options\": [\"森\", \"林\", \"木\", \"畑\"], \"answer\": \"森\", \"explanation\": \"Ba cây 木 tạo thành chữ 森 (SÂM - rừng rậm もり).\"}, {\"id\": 2, \"prompt\": \"2. Hai cái cây đứng cạnh nhau tạo thành rặng cây, lùm cây nhỏ:\", \"options\": [\"林\", \"森\", \"本\", \"休\"], \"answer\": \"林\", \"explanation\": \"Hai cây 木 tạo thành chữ 林 (LÂM - rặng cây はやし).\"}, {\"id\": 3, \"prompt\": \"3. Đống lửa củi (火) đặt cạnh mảnh ruộng (田) đốt rơm rạ:\", \"options\": [\"畑\", \"田\", \"森\", \"炎\"], \"answer\": \"畑\", \"explanation\": \"Lửa 火 + Ruộng 田 tạo thành chữ 畑 (nương rẫy, ruộng cạn はたけ).\"}, {\"id\": 4, \"prompt\": \"4. Núi (山) đá (石) sừng sững:\", \"options\": [\"岩\", \"山\", \"石\", \"炭\"], \"answer\": \"岩\", \"explanation\": \"Núi 山 trên Đá 石 tạo thành chữ 岩 (NHAM - tảng đá lớn いわ).\"}, {\"id\": 5, \"prompt\": \"5. Mặt trời chiếu sáng ban ngày (日) và mặt trăng soi rọi ban đêm (月):\", \"options\": [\"明\", \"晴\", \"朝\", \"暗\"], \"answer\": \"明\", \"explanation\": \"Nhật 日 kết hợp Nguyệt 月 tạo thành chữ 明 (MINH - sáng sủa あかるい).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 かんじの なかの かんじ (Bộ thủ A nằm trong chữ Hán B)', 'Xác định chữ Hán ở hàng B chứa đựng thành phần bộ thủ của chữ Hán ở hàng A (5 câu trang 105).', '/assets/kanji/n5/minigames/chap11_minigame_p105.webp', '"{\"example\": {\"prompt\": \"れい: Chữ A là 力 (Lực) -> nằm trong chữ B nào?\", \"answer\": \"男 (Nam)\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. Chữ A là 火 (Hỏa) nằm trong chữ B nào?\", \"options\": [\"畑\", \"暗\", \"森\", \"岩\"], \"answer\": \"畑\", \"explanation\": \"Chữ 火 là bộ bên trái của chữ 畑 (ruộng rẫy).\"}, {\"id\": 2, \"prompt\": \"2. Chữ A là 木 (Mộc) nằm trong chữ B nào?\", \"options\": [\"森\", \"畑\", \"明\", \"男\"], \"answer\": \"森\", \"explanation\": \"Chữ 木 nhân 3 lần tạo thành chữ 森 (rừng rậm).\"}, {\"id\": 3, \"prompt\": \"3. Chữ A là 石 (Thạch) nằm trong chữ B nào?\", \"options\": [\"岩\", \"暗\", \"畑\", \"明\"], \"answer\": \"岩\", \"explanation\": \"Chữ 石 nằm ở nửa dưới của chữ 岩 (tảng đá lớn).\"}, {\"id\": 4, \"prompt\": \"4. Chữ A là 音 (Âm) nằm trong chữ B nào?\", \"options\": [\"暗\", \"明\", \"森\", \"畑\"], \"answer\": \"暗\", \"explanation\": \"Chữ 音 kết hợp với chữ 日 tạo thành chữ 暗 (ÁM - tối tăm くらい).\"}, {\"id\": 5, \"prompt\": \"5. Chữ A là 月 (Nguyệt) nằm trong chữ B nào?\", \"options\": [\"明\", \"暗\", \"岩\", \"森\"], \"answer\": \"明\", \"explanation\": \"Chữ 月 là bộ bên phải của chữ 明 (MINH - sáng tỏ).\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 かんじを えらんで かきましょう (Điền chữ Hán vào câu)', 'Chọn từ thích hợp trong khung (畑, 林, 音, 明, 暗) điền vào 5 câu ở bài 【3】 trang 105.', '/assets/kanji/n5/minigames/chap11_minigame_p105.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"1. わたしの しゅみは [ ? ] で やさいを つくる ことです。\", \"options\": [\"畑 (はたけ)\", \"林 (はやし)\", \"森 (もり)\", \"岩 (いわ)\"], \"answer\": \"畑 (はたけ)\", \"explanation\": \"Trồng rau trên nương rẫy: 畑で野菜をつくる.\"}, {\"id\": 2, \"prompt\": \"2. 山田さんは [ ? ] ざんが とくいです。(Tính nhẩm giỏi)\", \"options\": [\"暗 (あん)\", \"明 (めい)\", \"音 (おん)\", \"林 (りん)\"], \"answer\": \"暗 (あん)\", \"explanation\": \"Tính nhẩm là 暗算 (あんざん), chữ 暗.\"}, {\"id\": 3, \"prompt\": \"3. 外で 大きな [ ? ] が しました。(Âm thanh lớn)\", \"options\": [\"音 (おと)\", \"暗 (くら)\", \"明 (あか)\", \"畑 (はたけ)\"], \"answer\": \"音 (おと)\", \"explanation\": \"Tiếng động, âm thanh là 音 (おと).\"}, {\"id\": 4, \"prompt\": \"4. わたしは りょうりが じょうずで [ ? ] るい人と けっこんしたいです。(Vui vẻ, tươi sáng)\", \"options\": [\"明 (あか)\", \"暗 (くら)\", \"畑 (はたけ)\", \"林 (はやし)\"], \"answer\": \"明 (あか)\", \"explanation\": \"Người tươi sáng, hoạt bát là 明るい人 (あかるいひと).\"}, {\"id\": 5, \"prompt\": \"5. 学校の ちかくの [ ? ] で よく あそびました。(Lùm cây gần trường)\", \"options\": [\"林 (はやし)\", \"畑 (はたけ)\", \"音 (おと)\", \"暗 (くら)\"], \"answer\": \"林 (はやし)\", \"explanation\": \"Khu rừng nhỏ gần trường là 林 (はやし).\"}]}"', 3, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
