        (v_ch_id, '方言', 'ほうげん', 'hougen', 'Tiếng địa phương', 'Dialect', 3, NOW()),
        (v_ch_id, '書く', 'かく', 'kaku', 'Viết, vẽ', 'To write', 4, NOW()),
        (v_ch_id, '辞書', 'じしょ', 'jisho', 'Từ điển', 'Dictionary', 5, NOW()),
        (v_ch_id, '読書', 'どくしょ', 'dokusho', 'Đọc sách', 'Reading books', 6, NOW()),
        (v_ch_id, '読む', 'よむ', 'yomu', 'Đọc', 'To read', 7, NOW()),
        (v_ch_id, '話す', 'はなす', 'hanasu', 'Nói chuyện, đàm thoại', 'To speak', 8, NOW()),
