        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'にほんごで [言います]。', '言います', 'いいます', '"[\"いいます\", \"かきます\", \"よみます\", \"はなします\"]"', '言います (nói) đọc là いいます.', 1, NOW()),
        (v_ch_id, 'READING', 'かぞくに てがみを [書きます]。', '書きます', 'かきます', '"[\"かきます\", \"よみます\", \"いいます\", \"ききます\"]"', '書きます (viết thư) đọc là かきます.', 2, NOW()),
        (v_ch_id, 'READING', 'あさ しんぶんを [読みます]。', '読みます', 'よみます', '"[\"よみます\", \"かきます\", \"みます\", \"たべます\"]"', '読みます (đọc báo) đọc là よみます.', 3, NOW()),
        (v_ch_id, 'READING', 'ともだちと たのしく [話します]。', '話します', 'はなします', '"[\"はなします\", \"いいます\", \"よみます\", \"あいます\"]"', '話します (nói chuyện) đọc là はなします.', 4, NOW()),
        (v_ch_id, 'READING', 'あさごはんを [食べます]。', '食べます', 'たべます', '"[\"たべます\", \"のみます\", \"かいます\", \"みます\"]"', '食べます (ăn sáng) đọc là たべます.', 5, NOW()),
        (v_ch_id, 'READING', 'おちゃを [飲みます]。', '飲みます', 'のみます', '"[\"のみます\", \"たべます\", \"すいます\", \"かいます\"]"', '飲みます (uống trà) đọc là のみます.', 6, NOW()),
        (v_ch_id, 'READING', 'スーパーで パンを [買います]。', '買います', 'かいます', '"[\"かいます\", \"うります\", \"たべます\", \"もちます\"]"', '買います (mua bánh) đọc là かいます.', 7, NOW()),
        (v_ch_id, 'READING', 'にほんごの [言葉]を おぼえます。', '言葉', 'ことば', '"[\"ことば\", \"げんよう\", \"いいは\", \"ことよう\"]"', '言葉 (từ vựng, ngôn từ) đọc là ことば.', 8, NOW()),
        (v_ch_id, 'READING', 'しゅみは [読書]です。', '読書', 'どくしょ', '"[\"どくしょ\", \"よみほん\", \"とうしょ\", \"どくほん\"]"', '読書 (đọc sách) đọc là どくしょ.', 9, NOW()),
        (v_ch_id, 'READING', 'ともだちに [電話]を かけます。', '電話', 'でんわ', '"[\"でんわ\", \"でんしゃ\", \"でんき\", \"でんわん\"]"', '電話 (điện thoại) đọc là でんわ.', 10, NOW()),
        (v_ch_id, 'WRITING', 'せんせいに [い]います。Kanji là:', 'い', '言', '"[\"言\", \"語\", \"話\", \"読\"]"', 'いう (nói) viết chữ Hán là 言う.', 1, NOW()),
        (v_ch_id, 'WRITING', 'ノートに [か]きます。Kanji là:', 'か', '書', '"[\"書\", \"画\", \"昼\", \"昼\"]"', 'かく (viết) viết chữ Hán là 書く.', 2, NOW()),
        (v_ch_id, 'WRITING', 'ほんを [よ]みます。Kanji là:', 'よ', '読', '"[\"読\", \"言\", \"語\", \"訳\"]"', 'よむ (đọc) viết chữ Hán là 読む.', 3, NOW()),
        (v_ch_id, 'WRITING', 'にほんごで [はな]します。Kanji là:', 'はな', '話', '"[\"話\", \"語\", \"言\", \"舌\"]"', 'はなす (nói chuyện) viết là 話す.', 4, NOW()),
        (v_ch_id, 'WRITING', 'すしを [た]べます。Kanji là:', 'た', '食', '"[\"食\", \"飲\", \"飯\", \"館\"]"', 'たべる (ăn) viết chữ Hán là 食べる.', 5, NOW()),
        (v_ch_id, 'WRITING', 'みずを [の]みます。Kanji là:', 'の', '飲', '"[\"飲\", \"食\", \"吸\", \"飯\"]"', 'のむ (uống) viết chữ Hán là 飲む.', 6, NOW()),
        (v_ch_id, 'WRITING', 'プレゼントを [か]います。Kanji là:', 'か', '買', '"[\"買\", \"売\", \"貝\", \"貸\"]"', 'かう (mua) viết chữ Hán là 買う.', 7, NOW()),
        (v_ch_id, 'WRITING', 'あたらしい [じしょ]を つかいます。Kanji là:', 'じしょ', '辞書', '"[\"辞書\", \"字書\", \"自書\", \"治書\"]"', 'じしょ (từ điển) viết là 辞書.', 8, NOW()),
        (v_ch_id, 'WRITING', '[でんわ]に でます。Kanji là:', 'でんわ', '電話', '"[\"電話\", \"電言\", \"電話\", \"伝話\"]"', 'でんわ viết là 電話.', 9, NOW()),
        (v_ch_id, 'WRITING', 'レストランで [しょくじ]を します。Kanji là:', 'しょくじ', '食事', '"[\"食事\", \"食次\", \"食時\", \"食字\"]"', 'しょくじ (bữa ăn) viết là 食事.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 かんじの ぶひん (Ghép bộ phận tạo chữ Hán động từ)', 'Ghép các bộ thủ cho sẵn (母, 売, 日, 良, 舌, 食, 貝) để hoàn thiện chữ Hán trong 6 câu ở trang 112.', '/assets/kanji/n5/minigames/chap12_minigame_p112.webp', '"{\"example\": {\"prompt\": \"れい: でん [ 言 ] を おねがいします\", \"answer\": \"言\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. [ ? ] み物は なにが いいですか。(Ghép 欠 + 食)\", \"options\": [\"飲\", \"食\", \"話\", \"買\"], \"answer\": \"飲\", \"explanation\": \"Khuyết 欠 kết hợp Thực 食 tạo thành chữ 飲 (ẨM - 飲み物 のみもの).\"}, {\"id\": 2, \"prompt\": \"2. でん [ ? ] を かけます。(Ghép 舌 + 言)\", \"options\": [\"話\", \"言\", \"書\", \"読\"], \"answer\": \"話\", \"explanation\": \"Thiệt 舌 kết hợp Ngôn 言 tạo thành chữ 話 (THOẠI - 電話 でんわ).\"}, {\"id\": 3, \"prompt\": \"3. [ ? ] べに 行きませんか。(Ghép 良 + 食)\", \"options\": [\"食\", \"飲\", \"買\", \"読\"], \"answer\": \"食\", \"explanation\": \"Lương 良 kết hợp 食 tạo thành chữ 食 (THỰC - 食べに たべに).\"}, {\"id\": 4, \"prompt\": \"4. じ [ ? ] で しらべます。(Ghép 聿 + 日)\", \"options\": [\"書\", \"言\", \"話\", \"読\"], \"answer\": \"書\", \"explanation\": \"Duật 聿 kết hợp Nhật 日 tạo thành chữ 書 (THƯ - 辞書 じしょ).\"}, {\"id\": 5, \"prompt\": \"5. スーパーで [ ? ] い物を します。(Ghép 罒 + 貝)\", \"options\": [\"買\", \"賣\", \"見\", \"物\"], \"answer\": \"買\", \"explanation\": \"Võng 罒 kết hợp Bối 貝 tạo thành chữ 買 (MÃI - 買い物 かいもの).\"}, {\"id\": 6, \"prompt\": \"6. 音 [ ? ] を します。(Ghép 売 + 言)\", \"options\": [\"読\", \"話\", \"書\", \"語\"], \"answer\": \"読\", \"explanation\": \"Mại 売 kết hợp Ngôn 言 tạo thành chữ 読 (ĐỘC - 音読 おんどく).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 サリーさんの にっき (Nhật ký mua sắm của Sally)', 'Đọc bài nhật ký đi chơi của Sally ở trang 112, chọn chữ Hán/cách đọc đúng cho đầy đủ 15 vị trí ① đến ⑮.', '/assets/kanji/n5/minigames/chap12_minigame_p112.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① マリアさんと [かいもの] に いきました\", \"options\": [\"買い物\", \"買物\", \"食物\", \"読物\"], \"answer\": \"買い物\", \"explanation\": \"かいもの viết là 買い物 (mua sắm).\"}, {\"id\": 2, \"prompt\": \"② かいものに [いき] ました\", \"options\": [\"行きました\", \"来ました\", \"帰りました\", \"出ました\"], \"answer\": \"行きました\", \"explanation\": \"いきました viết là 行きました (đã đi).\"}, {\"id\": 3, \"prompt\": \"③ デパートで [にせんえん] の サンダルを かいました\", \"options\": [\"二千円\", \"二万円\", \"二万円円\", \"二千元\"], \"answer\": \"二千円\", \"explanation\": \"にせんえん viết là 二千円 (2,000 yên).\"}, {\"id\": 4, \"prompt\": \"④ サンダルを [かい] ました\", \"options\": [\"買いました\", \"売りました\", \"話しました\", \"書きました\"], \"answer\": \"買いました\", \"explanation\": \"かいました viết là 買いました (đã mua).\"}, {\"id\": 5, \"prompt\": \"⑤ [ゆうめい] な カレーやで ひるごはんを たべました\", \"options\": [\"ゆう名な\", \"有名\", \"名まえ\", \"有力な\"], \"answer\": \"ゆう名な\", \"explanation\": \"ゆうめいな viết là ゆう名な (nổi tiếng).\"}, {\"id\": 6, \"prompt\": \"⑥ ひるごはんを [たべ] ました\", \"options\": [\"食べました\", \"飲みました\", \"話しました\", \"買い増した\"], \"answer\": \"食べました\", \"explanation\": \"たべました viết là 食べました (đã ăn).\"}, {\"id\": 7, \"prompt\": \"⑦ みせに [ひと] が たくさん いました\", \"options\": [\"人\", \"男\", \"女\", \"子\"], \"answer\": \"人\", \"explanation\": \"ひと viết là 人 (nhiều người).\"}, {\"id\": 8, \"prompt\": \"⑧ [なまえ] を かいて まちました\", \"options\": [\"名まえ\", \"名前\", \"文字\", \"言葉\"], \"answer\": \"名まえ\", \"explanation\": \"なまえ viết là 名まえ (tên).\"}, {\"id\": 9, \"prompt\": \"⑨ なまえを [かい] て まちました\", \"options\": [\"書いて\", \"言って\", \"話して\", \"読んで\"], \"answer\": \"書いて\", \"explanation\": \"かいて viết là 書いて (viết tên).\"}, {\"id\": 10, \"prompt\": \"⑩ [さんじっぷん] まちましたが よかったです\", \"options\": [\"30分\", \"30時\", \"30日\", \"30円\"], \"answer\": \"30分\", \"explanation\": \"さんじっぷん viết là 30分 (30 phút).\"}, {\"id\": 11, \"prompt\": \"⑪ マリアさんも よかったですと [いい] ました\", \"options\": [\"言いました\", \"話しました\", \"書きました\", \"聞きました\"], \"answer\": \"言いました\", \"explanation\": \"いいました viết là 言いました (đã nói).\"}, {\"id\": 12, \"prompt\": \"⑫ カフェで [おちゃ] を のみました\", \"options\": [\"お茶\", \"水\", \"酒\", \"牛乳\"], \"answer\": \"お茶\", \"explanation\": \"おちゃ viết là お茶 (trà xanh).\"}, {\"id\": 13, \"prompt\": \"⑬ おちゃを [のみ] ました\", \"options\": [\"飲みました\", \"食べました\", \"買いました\", \"吸いました\"], \"answer\": \"飲みました\", \"explanation\": \"のみました viết là 飲みました (đã uống).\"}, {\"id\": 14, \"prompt\": \"⑭ 2じかん [はなし] ました\", \"options\": [\"話しました\", \"言いました\", \"読みました\", \"聞きました\"], \"answer\": \"話しました\", \"explanation\": \"はなしました viết là 話しました (nói chuyện 2 tiếng).\"}, {\"id\": 15, \"prompt\": \"⑮ たのしい [いちにち] でした\", \"options\": [\"一日\", \"毎日\", \"休日\", \"今日\"], \"answer\": \"一日\", \"explanation\": \"いちにち viết là 一日 (một ngày vui vẻ).\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 なにを していますか (Mọi người đang làm gì trong phòng khách?)', 'Quan sát tranh sinh hoạt phòng khách trang 113 và chọn chữ Hán động từ thể て điền vào 6 câu.', '/assets/kanji/n5/minigames/chap12_minigame_p113.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"1. パットさんは 本を [ ? ] います。(Đang đọc sách)\", \"options\": [\"読んで (よんで)\", \"話して (はなして)\", \"書いて (かいて)\", \"見て (みて)\"], \"answer\": \"読んで (よんで)\", \"explanation\": \"Pat đang đọc sách: 本を読んでいます。\"}, {\"id\": 2, \"prompt\": \"2. トムさんは でんわで [ ? ] います。(Đang nói chuyện điện thoại)\", \"options\": [\"話して (はなして)\", \"言って (いって)\", \"聞いて (きいて)\", \"呼んで (よんで)\"], \"answer\": \"話して (はなして)\", \"explanation\": \"Tom đang nói chuyện qua điện thoại: でんわで話しています。\"}, {\"id\": 3, \"prompt\": \"3. ロビンさんは ジュースを [ ? ] います。(Đang mua nước ở máy bán hàng)\", \"options\": [\"買って (かって)\", \"飲んで (のんで)\", \"売って (うって)\", \"取って (とって)\"], \"answer\": \"買って (かって)\", \"explanation\": \"Robin đang mua nước tại cây bán tự động: ジュースを買っています。\"}, {\"id\": 4, \"prompt\": \"4. マリーさんは 音がくを [ ? ] います。(Đang đeo tai nghe nghe nhạc)\", \"options\": [\"聞いて (きいて)\", \"話して (はなして)\", \"読んで (よんで)\", \"見て (みて)\"], \"answer\": \"聞いて (きいて)\", \"explanation\": \"Marie đeo tai nghe thưởng thức âm nhạc: 音がくを聞いています。\"}, {\"id\": 5, \"prompt\": \"5. ジムさんは おかしを [ ? ] います。(Đang ăn bim bim)\", \"options\": [\"食べて (たべて)\", \"飲んで (のんで)\", \"買って (かって)\", \"作って (つくって)\"], \"answer\": \"食べて (たべて)\", \"explanation\": \"Jim ngồi ghế sofa ăn bánh kẹo: おかしを食べています。\"}, {\"id\": 6, \"prompt\": \"6. キャリーさんは お茶を [ ? ] います。(Đang uống tách trà)\", \"options\": [\"飲んで (のんで)\", \"食べて (たべて)\", \"買って (かって)\", \"注いで (そそいで)\"], \"answer\": \"飲んで (のんで)\", \"explanation\": \"Carrie đang nhâm nhi tách trà: お茶を飲んでいます。\"}]}"', 3, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
