        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'しずかな [町]に すんでいます。', '町', 'まち', '"[\"まち\", \"ちょう\", \"てら\", \"むら\"]"', '町 (thị trấn) đọc là まち.', 1, NOW()),
        (v_ch_id, 'READING', 'きょうとの [お寺]を みます。', 'お寺', 'おてら', '"[\"おてら\", \"おじ\", \"おみや\", \"おじいん\"]"', 'お寺 (ngôi chùa) đọc là おてら.', 2, NOW()),
        (v_ch_id, 'READING', '[電車]で つうきんします。', '電車', 'でんしゃ', '"[\"でんしゃ\", \"でんくるま\", \"でんき\", \"でんし\"]"', '電車 (tàu điện) đọc là でんしゃ.', 3, NOW()),
        (v_ch_id, 'READING', 'あたらしい [車]を かいました。', '車', 'くるま', '"[\"くるま\", \"しゃ\", \"じ\", \"ば\"]"', '車 (xe hơi) đọc là くるま.', 4, NOW()),
        (v_ch_id, 'READING', '[東京]へ りょこうします。', '東京', 'とうきょう', '"[\"とうきょう\", \"ひがしきょう\", \"ひがしけい\", \"とうけい\"]"', '東京 (Tokyo) đọc là とうきょう.', 5, NOW()),
        (v_ch_id, 'READING', 'えきの [西口]で まちあわせます。', '西口', 'にしぐち', '"[\"にしぐち\", \"せいぐち\", \"さいぐち\", \"にしこう\"]"', '西口 (cửa tây) đọc là にしぐち.', 6, NOW()),
        (v_ch_id, 'READING', '[南の] しまへ いきます。', '南の', 'みなみの', '"[\"みなみの\", \"なんの\", \"なんぽうの\", \"ひがしの\"]"', '南 (phía nam) đọc là みなみ.', 7, NOW()),
        (v_ch_id, 'READING', '[北海道]は ゆきが ふります。', '北海道', 'ほっかいどう', '"[\"ほっかいどう\", \"きたかいどう\", \"ほくかいどう\", \"ほくかいみち\"]"', '北海道 đọc là ほっかいどう.', 8, NOW()),
        (v_ch_id, 'READING', 'へやの [電気]を けします。', '電気', 'でんき', '"[\"でんき\", \"でんち\", \"でんりょく\", \"でんこう\"]"', '電気 (đèn điện) đọc là でんき.', 9, NOW()),
        (v_ch_id, 'READING', '[東西南北]を かくにんします。', '東西南北', 'とうざいなんぼく', '"[\"とうざいなんぼく\", \"ひがしにしみなみきた\", \"とうさいなんほく\", \"とうぜいなんぼく\"]"', '東西南北 (bốn phương đông tây nam bắc) đọc là とうざいなんぼく.', 10, NOW()),
        (v_ch_id, 'WRITING', 'ふるい [まち]を さんぽします。Kanji là:', 'まち', '町', '"[\"町\", \"街\", \"村\", \"丁\"]"', 'まち viết là 町.', 1, NOW()),
        (v_ch_id, 'WRITING', 'ゆうめいな [てら]を まいります。Kanji là:', 'てら', '寺', '"[\"寺\", \"時\", \"持\", \"待\"]"', 'てら (chùa) viết là 寺.', 2, NOW()),
        (v_ch_id, 'WRITING', '[でんしゃ]の きっぷを かいます。Kanji là:', 'でんしゃ', '電車', '"[\"電車\", \"雷車\", \"電東\", \"電行\"]"', 'でんしゃ viết là 電車.', 3, NOW()),
        (v_ch_id, 'WRITING', '[くるま]を ちゅうしゃじょうに とめます。Kanji là:', 'くるま', '車', '"[\"車\", \"軍\", \"庫\", \"東\"]"', 'くるま viết chữ Hán là 車.', 4, NOW()),
        (v_ch_id, 'WRITING', '[ひがし]から たいようが のぼります。Kanji là:', 'ひがし', '東', '"[\"東\", \"西\", \"南\", \"北\"]"', 'ひがし (hướng đông) viết là 東.', 5, NOW()),
        (v_ch_id, 'WRITING', '[にし]に ゆうひが しずみます。Kanji là:', 'にし', '西', '"[\"西\", \"東\", \"北\", \"南\"]"', 'にし (hướng tây) viết là 西.', 6, NOW()),
        (v_ch_id, 'WRITING', '[みなみ]のかぜが あたたかいです。Kanji là:', 'みなみ', '南', '"[\"南\", \"北\", \"西\", \"東\"]"', 'みなみ (hướng nam) viết là 南.', 7, NOW()),
        (v_ch_id, 'WRITING', '[きた]の くには さむいです。Kanji là:', 'きた', '北', '"[\"北\", \"比\", \"背\", \"南\"]"', 'きた (hướng bắc) viết là 北.', 8, NOW()),
        (v_ch_id, 'WRITING', 'へやの [でんき]を つけます。Kanji là:', 'でんき', '電気', '"[\"電気\", \"雷気\", \"電氣\", \"電空\"]"', 'でんき (điện) viết là 電気.', 9, NOW()),
        (v_ch_id, 'WRITING', '[とうきょう]えきで のりかえます。Kanji là:', 'とうきょう', '東京', '"[\"東京\", \"東都\", \"東県\", \"西京\"]"', 'とうきょう viết là 東京.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 のりものの クイズ (Câu đố về phương tiện giao thông)', 'Đọc đặc điểm 1 đến 6 ở trang 120 và chọn phương tiện tương ứng: A (電車), B (自動車), C (自転車).', '/assets/kanji/n5/minigames/chap13_minigame_p120.webp', '"{\"example\": {\"prompt\": \"れい: いちばん 大きいです (To lớn nhất)\", \"answer\": \"A (電車)\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. 二つの タイヤで うごきます (Chạy chuyển động bằng 2 bánh xe)\", \"options\": [\"C (じてん車)\", \"A (電車)\", \"B (じどう車)\", \"D (飛行機)\"], \"answer\": \"C (じてん車)\", \"explanation\": \"Xe chạy bằng 2 bánh là xe đạp 自転車 (C).\"}, {\"id\": 2, \"prompt\": \"2. 二人で のってはいけません (Luật cấm đèo 2 người)\", \"options\": [\"C (じてん車)\", \"B (じどう車)\", \"A (電車)\", \"D (バス)\"], \"answer\": \"C (じてん車)\", \"explanation\": \"Ở Nhật Bản xe đạp thông thường cấm kẹp hai người (C).\"}, {\"id\": 3, \"prompt\": \"3. 二十人 のることが できます (Có thể chở trên 20 người cùng lúc)\", \"options\": [\"A (電車)\", \"B (じどう車)\", \"C (じてん車)\", \"D (タクシー)\"], \"answer\": \"A (電車)\", \"explanation\": \"Tàu điện chở được số lượng lớn hành khách trên 20 người (A).\"}, {\"id\": 4, \"prompt\": \"4. ガソリンを つかいます (Phương tiện dùng nhiên liệu xăng)\", \"options\": [\"B (じどう車)\", \"A (電車)\", \"C (じてん車)\", \"D (地下鉄)\"], \"answer\": \"B (じどう車)\", \"explanation\": \"Xe ô tô dùng xăng chạy động cơ đốt trong 自動車 (B).\"}, {\"id\": 5, \"prompt\": \"5. おさけを 飲んでも のることができます (Say rượu vẫn đi được)\", \"options\": [\"A (電車)\", \"B (じどう車)\", \"C (じてん車)\", \"D (バイク)\"], \"answer\": \"A (電車)\", \"explanation\": \"Người uống rượu có thể đi phương tiện công cộng như tàu điện (A).\"}, {\"id\": 6, \"prompt\": \"6. 子どもも うんてんすることが できます (Trẻ em cũng tự điều khiển lái được)\", \"options\": [\"C (じてん車)\", \"A (電車)\", \"B (じどう車)\", \"D (トラック)\"], \"answer\": \"C (じてん車)\", \"explanation\": \"Trẻ con có thể tự đạp xe đạp 自転車 (C).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 かん字の けいさん (Phép toán đố chữ Kanji)', 'Thực hiện các phép tính cộng/trừ bộ thủ chữ Hán trang 120 (5 câu).', '/assets/kanji/n5/minigames/chap13_minigame_p120.webp', '"{\"example\": {\"prompt\": \"れい: 田 + 丁 = 町\", \"answer\": \"町\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. 土 + 寸 = [ ? ]\", \"options\": [\"寺\", \"時\", \"等\", \"持\"], \"answer\": \"寺\", \"explanation\": \"Thổ 土 kết hợp Thốn 寸 tạo thành chữ 寺 (TỰ - ngôi chùa おてら).\"}, {\"id\": 2, \"prompt\": \"2. 二 + 日 + 丨 = [ ? ]\", \"options\": [\"車\", \"東\", \"電\", \"重\"], \"answer\": \"車\", \"explanation\": \"Nét ngang 二 + Nhật 日 + sổ dọc xuyên tâm tạo thành chữ 車 (XA - xe cộ くるま).\"}, {\"id\": 3, \"prompt\": \"3. 酉 - 一 = [ ? ]\", \"options\": [\"西\", \"四\", \"酒\", \"配\"], \"answer\": \"西\", \"explanation\": \"Chữ Dậu 酉 bớt đi 1 nét ngang bên trong tạo thành chữ 西 (TÂY - hướng tây にし).\"}, {\"id\": 4, \"prompt\": \"4. 申 + 一 + 八 (hoặc 木 + 日) = [ ? ]\", \"options\": [\"東\", \"車\", \"重\", \"果\"], \"answer\": \"東\", \"explanation\": \"Mộc 木 kết hợp Nhật 日 tạo thành chữ 東 (ĐÔNG - hướng đông ひがし).\"}, {\"id\": 5, \"prompt\": \"5. 十 + 冂 + (羊 - 一) = [ ? ]\", \"options\": [\"南\", \"西\", \"北\", \"車\"], \"answer\": \"南\", \"explanation\": \"Thập 十 + Quynh 冂 + bộ Dương thiếu nét tạo thành chữ 南 (NAM - hướng nam みなみ).\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 さくぶん: かまくらりょこう (Bài văn: Chuyến du lịch Kamakura)', 'Đọc bài văn kể về chuyến đi chơi Kamakura của Julia trang 121, chọn chữ Hán đúng cho đầy đủ 18 câu từ ① đến ⑱.', '/assets/kanji/n5/minigames/chap13_minigame_p121.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① [せんげつ] の やすみに かまくらへ いきました\", \"options\": [\"先月\", \"今月\", \"来月\", \"毎月\"], \"answer\": \"先月\", \"explanation\": \"せんげつ viết là 先月 (tháng trước).\"}, {\"id\": 2, \"prompt\": \"② せんげつの [やすみ] に かまくらへ いきました\", \"options\": [\"休み\", \"休\", \"体\", \"本\"], \"answer\": \"休み\", \"explanation\": \"やすみ viết là 休み (kỳ nghỉ).\"}, {\"id\": 3, \"prompt\": \"③ [ともだち] と かまくらへ いきました\", \"options\": [\"友だち\", \"友達\", \"先生\", \"人\"], \"answer\": \"友だち\", \"explanation\": \"ともだち viết là 友だち (bạn bè).\"}, {\"id\": 4, \"prompt\": \"④ かまくらへ [いき] ました\", \"options\": [\"行きました\", \"来ました\", \"帰りました\", \"出ました\"], \"answer\": \"行きました\", \"explanation\": \"いきました viết là 行きました (đã đi).\"}, {\"id\": 5, \"prompt\": \"⑤ かまくらには ふるい [おてら] が たくさん あります\", \"options\": [\"お寺\", \"寺\", \"神社\", \"町\"], \"answer\": \"お寺\", \"explanation\": \"おてら viết là お寺 (chùa chiền cổ kính).\"}, {\"id\": 6, \"prompt\": \"⑥ [とうきょう] から でんしゃで 1じかんでした\", \"options\": [\"東きょう\", \"東京\", \"西きょう\", \"北きょう\"], \"answer\": \"東きょう\", \"explanation\": \"とうきょう viết trong sách là 東きょう (chữ 東 trong 東京).\"}, {\"id\": 7, \"prompt\": \"⑦ とうきょうから [でんしゃ] で 1じかんでした\", \"options\": [\"電車\", \"車\", \"じてん車\", \"汽車\"], \"answer\": \"電車\", \"explanation\": \"でんしゃ viết là 電車 (tàu điện).\"}, {\"id\": 8, \"prompt\": \"⑧ かまくらえきで [じてんしゃ] を かりて いろいろな ばしょへ いきました\", \"options\": [\"じてん車\", \"自転車\", \"電車\", \"自動車\"], \"answer\": \"じてん車\", \"explanation\": \"じてんしゃ viết trong bài là じてん車 (xe đạp).\"}, {\"id\": 9, \"prompt\": \"⑨ おひるごはんは [ゆうめい] な そばやで そばを たべました\", \"options\": [\"ゆう名な\", \"有名\", \"名前\", \"有名な\"], \"answer\": \"ゆう名な\", \"explanation\": \"ゆうめいな viết là ゆう名な (nổi tiếng).\"}, {\"id\": 10, \"prompt\": \"⑩ そばを [たべ] ました\", \"options\": [\"食べました\", \"飲みました\", \"買いました\", \"見ました\"], \"answer\": \"食べました\", \"explanation\": \"たべました viết là 食べました (đã ăn).\"}, {\"id\": 11, \"prompt\": \"⑪ [ほん] で しらべて まえの ひに よやくしました\", \"options\": [\"本\", \"体\", \"言\", \"書\"], \"answer\": \"本\", \"explanation\": \"ほんで viết là 本で (tra cứu trong sách).\"}, {\"id\": 12, \"prompt\": \"⑫ まえの [ひ] に でんわで よやくしました\", \"options\": [\"日\", \"月\", \"年\", \"時\"], \"answer\": \"日\", \"explanation\": \"ひに viết là 日に (vào ngày hôm trước).\"}, {\"id\": 13, \"prompt\": \"⑬ まえの ひに [でんわ] で よやくしました\", \"options\": [\"電話\", \"手紙\", \"電車\", \"会話\"], \"answer\": \"電話\", \"explanation\": \"でんわ viết là 電話 (gọi điện thoại).\"}, {\"id\": 14, \"prompt\": \"⑭ ごはんを [たべ] て うみへ いきました\", \"options\": [\"食べて\", \"飲んで\", \"行って\", \"買って\"], \"answer\": \"食べて\", \"explanation\": \"たべて viết là 食べて (ăn xong đi ra biển).\"}, {\"id\": 15, \"prompt\": \"⑮ きれいな [かい] を ひろいました\", \"options\": [\"貝\", \"見\", \"魚\", \"石\"], \"answer\": \"貝\", \"explanation\": \"かい viết là 貝 (vỏ sò biển).\"}, {\"id\": 16, \"prompt\": \"⑯ おみやげも [かっ] て かえりました\", \"options\": [\"買って\", \"売って\", \"持って\", \"取って\"], \"answer\": \"買って\", \"explanation\": \"かって viết là 買って (mua quà lưu niệm).\"}, {\"id\": 17, \"prompt\": \"⑰ おみやげも かって [かえり] ました\", \"options\": [\"帰りました\", \"行きました\", \"来ました\", \"出ました\"], \"answer\": \"帰りました\", \"explanation\": \"かえりました viết là 帰りました (trở về).\"}, {\"id\": 18, \"prompt\": \"⑱ たのしい [いちにち] でした\", \"options\": [\"一日\", \"毎日\", \"休日\", \"今日\"], \"answer\": \"一日\", \"explanation\": \"いちにち viết là 一日 (một ngày trọn vẹn tuyệt vời).\"}]}"', 3, NOW());
        INSERT INTO kanji_chapter_vocab (chapter_id, word, reading, romaji, meaning_vi, meaning_en, display_order, created_at) VALUES
        (v_ch_id, '時', 'とき', 'toki', 'Khi, lúc', 'Time, when', 1, NOW()),
