        (v_ch_id, '時計', 'とけい', 'tokei', 'Đồng hồ', 'Clock, watch', 3, NOW()),
        (v_ch_id, '間', 'あいだ', 'aida', 'Ở giữa, khoảng thời gian', 'Between, interval', 4, NOW()),
        (v_ch_id, '間に合う', 'まにあう', 'maniau', 'Kịp giờ', 'To be in time', 5, NOW()),
        (v_ch_id, '人間', 'にんげん', 'ningen', 'Con người, nhân loại', 'Human being', 6, NOW()),
        (v_ch_id, '半分', 'はんぶん', 'hanbun', 'Một nửa', 'Half', 7, NOW()),
        (v_ch_id, '一時半', 'いちじはん', 'ichijihan', '1 giờ rưỡi', '1:30', 8, NOW()),
        (v_ch_id, '分', 'ふん / ぷん', 'fun', 'Phút', 'Minute', 9, NOW()),
        (v_ch_id, '分かる', 'わかる', 'wakaru', 'Hiểu, nhận biết', 'To understand', 10, NOW()),
        (v_ch_id, '今', 'いま', 'ima', 'Bây giờ, hiện tại', 'Now', 11, NOW()),
        (v_ch_id, '今日', 'きょう', 'kyou', 'Hôm nay', 'Today', 12, NOW()),
        (v_ch_id, '今月', 'こんげつ', 'kongetsu', 'Tháng này', 'This month', 13, NOW()),
        (v_ch_id, '今年', 'ことし', 'kotoshi', 'Năm nay', 'This year', 14, NOW()),
        (v_ch_id, '何', 'なに / なん', 'nani', 'Cái gì', 'What', 15, NOW()),
