        (v_ch_id, '何人', 'なんにん', 'nannin', 'Mấy người', 'How many people', 17, NOW()),
        (v_ch_id, '夕方', 'ゆうがた', 'yuugata', 'Hoàng hôn, chiều tối', 'Evening', 18, NOW()),
        (v_ch_id, '夕食', 'ゆうしょく', 'yuushoku', 'Bữa cơm tối', 'Dinner', 19, NOW()),
        (v_ch_id, '方', 'かた', 'kata', 'Người (kính ngữ), phương hướng', 'Person, way', 20, NOW());
        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', 'いま なん[時]ですか。', '時', 'じ', '"[\"じ\", \"とき\", \"かん\", \"ふん\"]"', '何時 (mấy giờ): chữ 時 đọc là じ.', 1, NOW()),
        (v_ch_id, 'READING', 'まいあさ 1[時間] べんきょうします。', '時間', 'じかん', '"[\"じかん\", \"ときあいだ\", \"じあいだ\", \"じけん\"]"', '時間 (thời gian / tiếng đồng hồ) đọc là じかん.', 2, NOW()),
        (v_ch_id, 'READING', '2じ[半]に えきで あいましょう。', '半', 'はん', '"[\"はん\", \"なかば\", \"はんぶん\", \"ぶん\"]"', '2時半 (2 giờ rưỡi) đọc là にじはん.', 3, NOW()),
        (v_ch_id, 'READING', '10[分] やすみましょう。', '分', 'ぷん', '"[\"ぷん\", \"ふん\", \"ぶん\", \"ぶ\"]"', '10分 (10 phút) đọc biến âm là じゅっぷん (ぷん).', 4, NOW()),
        (v_ch_id, 'READING', '[今] なんじですか。', '今', 'いま', '"[\"いま\", \"こん\", \"きょう\", \"こ\"]"', '今 (bây giờ) đọc là いま.', 5, NOW()),
        (v_ch_id, 'READING', 'これは [何]ですか。', '何', 'なん', '"[\"なん\", \"なに\", \"か\", \"どこ\"]"', '何ですか (cái gì vậy) đọc là なんですか.', 6, NOW()),
        (v_ch_id, 'READING', '[夕方] すずしくなりました。', '夕方', 'ゆうがた', '"[\"ゆうがた\", \"ゆうほう\", \"せきがた\", \"よるがた\"]"', '夕方 (chiều tối) đọc là ゆうがた.', 7, NOW()),
        (v_ch_id, 'READING', 'あのかたの [方]へ あるきます。', '方', 'ほう', '"[\"ほう\", \"かた\", \"がた\", \"き\"]"', 'あの方へ (về phía hướng đó) đọc là ほう.', 8, NOW()),
        (v_ch_id, 'READING', '[今年] にほんへ いきます。', '今年', 'ことし', '"[\"ことし\", \"こんねん\", \"いまねん\", \"きねん\"]"', '今年 (năm nay) là từ đặc biệt đọc là ことし.', 9, NOW()),
        (v_ch_id, 'READING', 'かぞくと [夕食]を たべます。', '夕食', 'ゆうしょく', '"[\"ゆうしょく\", \"よるしょく\", \"せきしょく\", \"ばんしょく\"]"', '夕食 (bữa cơm chiều tối) đọc là ゆうしょく.', 10, NOW()),
        (v_ch_id, 'WRITING', '[じかん]を まもります。Kanji là:', 'じかん', '時間', '"[\"時間\", \"時関\", \"時門\", \"事間\"]"', 'じかん viết là 時間.', 1, NOW()),
        (v_ch_id, 'WRITING', '3じ[はん]に おわります。Kanji là:', 'はん', '半', '"[\"半\", \"判\", \"伴\", \"平\"]"', 'はん (rưỡi, nửa) viết chữ Hán là 半.', 2, NOW()),
        (v_ch_id, 'WRITING', 'ご[ふん] まってください。Kanji là:', 'ふん', '分', '"[\"分\", \"刀\", \"粉\", \"份\"]"', 'ふん (phút) viết chữ Hán là 分.', 3, NOW()),
        (v_ch_id, 'WRITING', '[いま] なんじですか。Kanji là:', 'いま', '今', '"[\"今\", \"令\", \"合\", \"会\"]"', 'いま (bây giờ) viết chữ Hán là 今.', 4, NOW()),
        (v_ch_id, 'WRITING', 'あさごはんに [なに]を たべましたか。Kanji là:', 'なに', '何', '"[\"何\", \"荷\", \"可\", \"向\"]"', 'なに (cái gì) viết chữ Hán là 何.', 5, NOW()),
        (v_ch_id, 'WRITING', '[ゆうがた] かいものに いきます。Kanji là:', 'ゆうがた', '夕方', '"[\"夕方\", \"多方\", \"夜方\", \"暮方\"]"', 'ゆうがた viết là 夕方.', 6, NOW()),
        (v_ch_id, 'WRITING', 'かんじの かき[かた]を おしえてください。Kanji là:', 'かた', '方', '"[\"方\", \"万\", \"力\", \"片\"]"', 'かた (cách làm) viết chữ Hán là 方.', 7, NOW()),
        (v_ch_id, 'WRITING', '[なんじ]に おきますか。Kanji là:', 'なんじ', '何時', '"[\"何時\", \"何じ\", \"荷時\", \"幾時\"]"', 'なんじ viết là 何時.', 8, NOW()),
        (v_ch_id, 'WRITING', '[きょう]は いい てんきです。Kanji là:', 'きょう', '今日', '"[\"今日\", \"今月\", \"今年\", \"金日\"]"', 'きょう viết là 今日.', 9, NOW()),
        (v_ch_id, 'WRITING', '[はんぶん] こどもに あげました。Kanji là:', 'はんぶん', '半分', '"[\"半分\", \"半文\", \"判分\", \"伴分\"]"', 'はんぶん (một nửa) viết là 半分.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 ふじ山りょこうの パンフレット (Tờ rơi du lịch núi Phú Sĩ)', 'Dựa vào tờ rơi du lịch Phú Sĩ và hội thoại trang 128, điền đầy đủ chữ Hán đúng cho 9 vị trí ① đến ⑨.', '/assets/kanji/n5/minigames/chap14_minigame_p128.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① あなた: もしもし、田中さん (いま) [ ? ] 話しても いいですか。\", \"options\": [\"今\", \"金\", \"令\", \"合\"], \"answer\": \"今\", \"explanation\": \"いま viết là chữ 今 (bây giờ).\"}, {\"id\": 2, \"prompt\": \"② 田中さん: はい、(なん) [ ? ] ですか。\", \"options\": [\"何\", \"荷\", \"河\", \"苛\"], \"answer\": \"何\", \"explanation\": \"なん viết là chữ 何 (cái gì).\"}, {\"id\": 3, \"prompt\": \"③ 田中さん: 30日は (なん) [ ? ] よう日ですか。\", \"options\": [\"何\", \"荷\", \"今\", \"幾\"], \"answer\": \"何\", \"explanation\": \"なんようび viết là 何曜日 (thứ mấy).\"}, {\"id\": 4, \"prompt\": \"④ あなた: [ ? ] よう日です。(Nhìn tờ rơi: 5月30日(土))\", \"options\": [\"土\", \"日\", \"月\", \"金\"], \"answer\": \"土\", \"explanation\": \"Tờ rơi ghi rõ (土) tức 土曜日 (thứ Bảy).\"}, {\"id\": 5, \"prompt\": \"⑤ 田中さん: (なんじ) [ ? ] の バスですか。\", \"options\": [\"何時\", \"日時\", \"幾時\", \"今時\"], \"answer\": \"何時\", \"explanation\": \"なんじ viết là chữ 何時 (mấy giờ).\"}, {\"id\": 6, \"prompt\": \"⑥ あなた: 9 [ ? ] です。(Nhìn tờ rơi: 9:30)\", \"options\": [\"時半\", \"分\", \"時間\", \"時\"], \"answer\": \"時半\", \"explanation\": \"9:30 nói bằng chữ Hán là 9時半 (chín rưỡi).\"}, {\"id\": 7, \"prompt\": \"⑦ あなた: (おとな) [ ? ] は 一人 7,500円ですよ。\", \"options\": [\"大人\", \"小人\", \"男の人\", \"女の人\"], \"answer\": \"大人\", \"explanation\": \"おとな viết là chữ 大人 (người lớn: 7,500 yên).\"}, {\"id\": 8, \"prompt\": \"⑧ あなた: そうですね。(きょう) [ ? ] ARCツアーに 電話します。\", \"options\": [\"今日\", \"今月\", \"今年\", \"毎日\"], \"answer\": \"今日\", \"explanation\": \"きょう viết là 今日 (hôm nay).\"}, {\"id\": 9, \"prompt\": \"⑨ あなた: ARCツアーに [ ? ] して よやくします。\", \"options\": [\"電話\", \"手紙\", \"電車\", \"会話\"], \"answer\": \"電話\", \"explanation\": \"でんわして viết là 電話して (gọi điện thoại đặt chỗ).\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 AとBを あわせて かん字を つくりましょう (Ghép bộ thủ A và B tạo chữ Hán)', 'Ghép các bộ thủ ở hộp A (日, 亻, 人, 門, 言, 八) với hộp B (売, ラ, 可, 刀, 寺, 日) để tạo thành chữ Hán thời gian (5 câu trang 129).', '/assets/kanji/n5/minigames/chap14_minigame_p129.webp', '"{\"example\": {\"prompt\": \"れい: 言 + 売\", \"answer\": \"読\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. Ghép A: 日 + B: 寺 = [ ? ]\", \"options\": [\"時\", \"待\", \"持\", \"特\"], \"answer\": \"時\", \"explanation\": \"Nhật 日 + Tự 寺 tạo thành chữ 時 (THỜI - thời gian, giờ giấc じかん).\"}, {\"id\": 2, \"prompt\": \"2. Ghép A: 八 + B: 刀 = [ ? ]\", \"options\": [\"分\", \"切\", \"刃\", \"初\"], \"answer\": \"分\", \"explanation\": \"Bát 八 + Đao 刀 tạo thành chữ 分 (PHÂN - phút, phân chia ぷん).\"}, {\"id\": 3, \"prompt\": \"3. Ghép A: 人 + B: ラ = [ ? ]\", \"options\": [\"今\", \"令\", \"会\", \"合\"], \"answer\": \"今\", \"explanation\": \"Nhân 人 + ラ tạo thành chữ 今 (KIM - bây giờ いま).\"}, {\"id\": 4, \"prompt\": \"4. Ghép A: 門 + B: 日 = [ ? ]\", \"options\": [\"間\", \"問\", \"開\", \"聞\"], \"answer\": \"間\", \"explanation\": \"Môn 門 + Nhật 日 tạo thành chữ 間 (GIAN - khoảng thời gian あいだ).\"}, {\"id\": 5, \"prompt\": \"5. Ghép A: 亻 + B: 可 = [ ? ]\", \"options\": [\"何\", \"河\", \"荷\", \"歌\"], \"answer\": \"何\", \"explanation\": \"Nhân đứng 亻 + Khả 可 tạo thành chữ 何 (HÀ - cái gì, mấy なに).\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 かん字の 読み方を 書きましょう (Cách đọc chữ Hán trong câu phỏng vấn)', 'Đọc các câu hỏi hội thoại bạn bè ở bài 【3】 trang 129 và chọn cách đọc Furigana chuẩn xác cho đầy đủ 6 chữ Hán gạch chân.', '/assets/kanji/n5/minigames/chap14_minigame_p129.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① 友だち: いつも [何時] に おきますか。\", \"options\": [\"なんじ\", \"いつじ\", \"なんとき\", \"どき\"], \"answer\": \"なんじ\", \"explanation\": \"何時に đọc là なんじに (thức dậy lúc mấy giờ).\"}, {\"id\": 2, \"prompt\": \"② 友だち: しゅみは [何] ですか。\", \"options\": [\"なん\", \"なに\", \"どこ\", \"だれ\"], \"answer\": \"なん\", \"explanation\": \"何ですか đọc là なんですか (sở thích là gì).\"}, {\"id\": 3, \"prompt\": \"③ 友だち: [今日] の ごご 時間が ありますか。\", \"options\": [\"きょう\", \"こんにち\", \"いまひ\", \"きょうび\"], \"answer\": \"きょう\", \"explanation\": \"今日の đọc là きょうの (chiều ngày hôm nay).\"}, {\"id\": 4, \"prompt\": \"④ 友だち: 今日の ごご [時間] が ありますか。\", \"options\": [\"じかん\", \"ときま\", \"じま\", \"かんじ\"], \"answer\": \"じかん\", \"explanation\": \"時間が đọc là じかんが (có thời gian/rảnh không).\"}, {\"id\": 5, \"prompt\": \"⑤ 友だち: [今] いちばん 何が ほしいですか。\", \"options\": [\"いま\", \"こん\", \"きょう\", \"ほん\"], \"answer\": \"いま\", \"explanation\": \"今は đọc là いま (bây giờ).\"}, {\"id\": 6, \"prompt\": \"⑥ 友だち: 今 いちばん [何] が ほしいですか。\", \"options\": [\"なに\", \"なん\", \"どれ\", \"どちら\"], \"answer\": \"なに\", \"explanation\": \"何が đọc là なにが (muốn có thứ gì nhất).\"}]}"', 3, NOW());
