        INSERT INTO kanji_exercises (chapter_id, exercise_type, question_text, target_word, correct_answer, options_json, explanation, display_order, created_at) VALUES
        (v_ch_id, 'READING', '[新しい] くるまを かいました。', '新しい', 'あたらしい', '"[\"あたらしい\", \"ふるい\", \"しんしい\", \"やすい\"]"', '新しい (mới mẻ) đọc là あたらしい.', 1, NOW()),
        (v_ch_id, 'READING', '[古い] ほんを リサイクルします。', '古い', 'ふるい', '"[\"ふるい\", \"こい\", \"あたらしい\", \"ながい\"]"', '古い (cũ kỹ) đọc là ふるい.', 2, NOW()),
        (v_ch_id, 'READING', 'かみのけが [長い]です。', '長い', 'ながい', '"[\"ながい\", \"ちょうい\", \"みじかい\", \"おおい\"]"', '長い (dài) đọc là ながい.', 3, NOW()),
        (v_ch_id, 'READING', 'このりんごは とても [安い]です。', '安い', 'やすい', '"[\"やすい\", \"あんい\", \"たかい\", \"ひろい\"]"', '安い (rẻ) đọc là やすい.', 4, NOW()),
        (v_ch_id, 'READING', 'まちに ひとが [多い]です。', '多い', 'おおい', '"[\"おおい\", \"すくない\", \"たい\", \"すこし\"]"', '多い (nhiều người) đọc là おおい.', 5, NOW()),
        (v_ch_id, 'READING', 'みずを [少し] ください。', '少し', 'すこし', '"[\"すこし\", \"すくない\", \"しょうし\", \"おおい\"]"', '少し (một chút) đọc là すこし.', 6, NOW()),
        (v_ch_id, 'READING', 'おじいさんは いつも [元気]です。', '元気', 'げんき', '"[\"げんき\", \"がんき\", \"もとき\", \"げんけ\"]"', '元気 (khỏe mạnh) đọc là げんき.', 7, NOW()),
        (v_ch_id, 'READING', 'まいあさ [新聞]を よみます。', '新聞', 'しんぶん', '"[\"しんぶん\", \"あたらしきき\", \"しんもん\", \"あたらしぶん\"]"', '新聞 (tờ báo) đọc là しんぶん.', 8, NOW()),
        (v_ch_id, 'READING', 'かぞくの こえを きいて [安心]しました。', '安心', 'あんしん', '"[\"あんしん\", \"やすこころ\", \"あんじん\", \"やすしん\"]"', '安心 (yên tâm) đọc là あんしん.', 9, NOW()),
        (v_ch_id, 'READING', 'きょうは いい [天気]です。', '天気', 'てんき', '"[\"てんき\", \"あめき\", \"てんけ\", \"そらき\"]"', '天気 (thời tiết) đọc là てんき.', 10, NOW()),
        (v_ch_id, 'WRITING', '[あたら]しい スマホを かいました。Kanji là:', 'あたら', '新', '"[\"新\", \"親\", \"薪\", \"森\"]"', 'あたらしい (mới) viết là 新しい.', 1, NOW()),
        (v_ch_id, 'WRITING', '[ふる]い おてらを けんがくします。Kanji là:', 'ふる', '古', '"[\"古\", \"右\", \"吉\", \"舌\"]"', 'ふるい (cũ, cổ kính) viết chữ Hán là 古い.', 2, NOW()),
        (v_ch_id, 'WRITING', '[なが]い やすみを とります。Kanji là:', 'なが', '長', '"[\"長\", \"張\", \"髪\", \"帳\"]"', 'ながい (dài) viết chữ Hán là 長い.', 3, NOW()),
        (v_ch_id, 'WRITING', '[やす]い レストランを みつけました。Kanji là:', 'やす', '安', '"[\"安\", \"案\", \"按\", \"宴\"]"', 'やすい (rẻ tiền) viết chữ Hán là 安い.', 4, NOW()),
        (v_ch_id, 'WRITING', 'くるまが [おお]くて こみます。Kanji là:', 'おお', '多', '"[\"多\", \"夕\", \"名\", \"移\"]"', 'おおい (nhiều) viết chữ Hán là 多い.', 5, NOW()),
        (v_ch_id, 'WRITING', '[すこ]し つかれました。Kanji là:', 'すこ', '少', '"[\"少\", \"小\", \"抄\", \"省\"]"', 'すこし (một chút) viết chữ Hán là 少し.', 6, NOW()),
        (v_ch_id, 'WRITING', 'せんせい、お[げんき]ですか。Kanji là:', 'げんき', '元気', '"[\"元気\", \"源気\", \"原気\", \"言気\"]"', 'げんき viết là 元気.', 7, NOW()),
        (v_ch_id, 'WRITING', 'まいあさ [しんぶん]を はいたつします。Kanji là:', 'しんぶん', '新聞', '"[\"新聞\", \"親聞\", \"新門\", \"新問\"]"', 'しんぶん viết là 新聞.', 8, NOW()),
        (v_ch_id, 'WRITING', '[あんぜん]だいいちで はたらきます。Kanji là:', 'あんぜん', '安全', '"[\"安全\", \"安前\", \"暗全\", \"按全\"]"', 'あんぜん (an toàn) viết là 安全.', 9, NOW()),
        (v_ch_id, 'WRITING', 'あしたの [てんき]よほうを みます。Kanji là:', 'てんき', '天気', '"[\"天気\", \"天汽\", \"天木\", \"天機\"]"', 'てんき (thời tiết) viết là 天気.', 10, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【1】 ヒントを よんで かんじを かきましょう (Đọc gợi ý chọn tính từ)', 'Đọc gợi ý tình huống tương ứng trong từng khung ở trang 136 và chọn tính từ chuẩn xác (6 câu).', '/assets/kanji/n5/minigames/chap15_minigame_p136.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"1. あの レストランは おきゃくさんが [ ? ] ないですね。(ヒント: あまり 人が いません)\", \"options\": [\"少 (すく)\", \"多 (おお)\", \"新 (あたら)\", \"古 (ふる)\"], \"answer\": \"少 (すく)\", \"explanation\": \"Vắng khách, ít người: 少ない (すくない). Chữ 少.\"}, {\"id\": 2, \"prompt\": \"2. しぶやは わかい 人が [ ? ] い まちです。(ヒント: たくさん 人が います)\", \"options\": [\"多 (おお)\", \"少 (すく)\", \"高 (たか)\", \"安 (やす)\"], \"answer\": \"多 (おお)\", \"explanation\": \"Nhiều người, đông đúc: 多い (おおい). Chữ 多.\"}, {\"id\": 3, \"prompt\": \"3. わたしの 車は [ ? ] しいです。(ヒント: 3日まえに 買いました)\", \"options\": [\"新 (あたら)\", \"古 (ふる)\", \"安 (やす)\", \"高 (たか)\"], \"answer\": \"新 (あたら)\", \"explanation\": \"Xe mới mua 3 ngày trước: 新しい (あたらしい). Chữ 新.\"}, {\"id\": 4, \"prompt\": \"4. わたしの とけいは とても [ ? ] いです。(ヒント: 10年まえに 友だちに もらいました)\", \"options\": [\"古 (ふる)\", \"新 (あたら)\", \"安 (やす)\", \"少 (すく)\"], \"answer\": \"古 (ふる)\", \"explanation\": \"Đồng hồ cũ được tặng 10 năm trước: 古い (ふるい). Chữ 古.\"}, {\"id\": 5, \"prompt\": \"5. このりんごは とても [ ? ] かったです。(ヒント: スーパーで 200円でした)\", \"options\": [\"安 (やす)\", \"高 (たか)\", \"少 (すく)\", \"新 (あたら)\"], \"answer\": \"安 (やす)\", \"explanation\": \"Táo siêu thị giảm giá chỉ 200 yên rất rẻ: 安かった (やすかった). Chữ 安.\"}, {\"id\": 6, \"prompt\": \"6. このゆびわは とても [ ? ] かったです。(ヒント: ボーナスで 買いました 500,000円)\", \"options\": [\"高 (たか)\", \"安 (やす)\", \"新 (あたら)\", \"多 (おお)\"], \"answer\": \"高 (たか)\", \"explanation\": \"Nhẫn kim cương 500,000 yên rất đắt: 高かった (たかかった). Chữ 高.\"}]}"', 1, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【2】 かん字を つくりましょう (Phép cộng bộ thủ tạo chữ Kanji)', 'Ghép các bộ thủ được cộng lại ở bài 【2】 trang 137 để tạo thành chữ Hán tính từ/trạng thái (5 câu).', '/assets/kanji/n5/minigames/chap15_minigame_p137.webp', '"{\"example\": {\"prompt\": \"れい: 日 + 月 -> 明\", \"answer\": \"明\"}, \"questions\": [{\"id\": 1, \"prompt\": \"1. 宀 + 女 -> [ ? ]\", \"options\": [\"安\", \"字\", \"家\", \"好\"], \"answer\": \"安\", \"explanation\": \"Bộ Miên 宀 trên đầu người phụ nữ 女 tạo thành chữ 安 (AN - an toàn, rẻ やすい).\"}, {\"id\": 2, \"prompt\": \"2. 夕 + 夕 -> [ ? ]\", \"options\": [\"多\", \"名\", \"外\", \"夜\"], \"answer\": \"多\", \"explanation\": \"Hai bộ Tịch 夕 xếp chồng lên nhau tạo thành chữ 多 (ĐA - nhiều おおい).\"}, {\"id\": 3, \"prompt\": \"3. 小 + 丿 -> [ ? ]\", \"options\": [\"少\", \"小\", \"水\", \"不\"], \"answer\": \"少\", \"explanation\": \"Chữ Tiểu 小 thêm nét phẩy dài bên dưới tạo thành chữ 少 (THIỂU - ít すくない).\"}, {\"id\": 4, \"prompt\": \"4. 立 + 木 + 斤 -> [ ? ]\", \"options\": [\"新\", \"親\", \"析\", \"近\"], \"answer\": \"新\", \"explanation\": \"Chữ Lập 立 + Mộc 木 + Cân 斤 tạo thành chữ 新 (TÂN - mới あたらしい).\"}, {\"id\": 5, \"prompt\": \"5. 二 + 儿 -> [ ? ]\", \"options\": [\"元\", \"兄\", \"光\", \"先\"], \"answer\": \"元\", \"explanation\": \"Chữ Nhị 二 + Nhi 儿 tạo thành chữ 元 (NGUYÊN - nguồn gốc, khỏe mạnh げんき).\"}]}"', 2, NOW());
        INSERT INTO kanji_minigames (chapter_id, game_type, title, instruction, image_url, game_data_json, display_order, created_at) VALUES (v_ch_id, 'PICTURE_MATCH', '【3】 トムさんの 子どもの さくぶん (Bài văn: Bố Tom kể về con gái Marie)', 'Đọc bài văn ngắn của bố Tom kể về cô con gái Marie ở trang 137, chọn chữ Hán/cách đọc đúng cho đầy đủ 15 vị trí từ ① đến ⑮.', '/assets/kanji/n5/minigames/chap15_minigame_p137.webp', '"{\"questions\": [{\"id\": 1, \"prompt\": \"① わたしの [こども] の 名まえは マリーです\", \"options\": [\"子ども\", \"男の子\", \"女の子\", \"大人\"], \"answer\": \"子ども\", \"explanation\": \"こども viết là 子ども (con của tôi).\"}, {\"id\": 2, \"prompt\": \"② わたしの 子どもの [なまえ] は マリーです\", \"options\": [\"名まえ\", \"文字\", \"言葉\", \"名前\"], \"answer\": \"名まえ\", \"explanation\": \"なまえ viết là 名まえ (tên gọi).\"}, {\"id\": 3, \"prompt\": \"③ [ことし] 5さいです\", \"options\": [\"今年\", \"来年\", \"去年\", \"毎日\"], \"answer\": \"今年\", \"explanation\": \"ことし viết là 今年 (năm nay bé 5 tuổi).\"}, {\"id\": 4, \"prompt\": \"④ かみが [ながくて] かわいい 女の子です\", \"options\": [\"長くて\", \"短くて\", \"多くて\", \"高くて\"], \"answer\": \"長くて\", \"explanation\": \"ながくて viết là 長くて (mái tóc dài xinh xắn).\"}, {\"id\": 5, \"prompt\": \"⑤ かわいい [おんなのこ] です\", \"options\": [\"女の子\", \"男の子\", \"女の人\", \"子ども\"], \"answer\": \"女の子\", \"explanation\": \"おんなのこ viết là 女の子 (bé gái).\"}, {\"id\": 6, \"prompt\": \"⑥ [にほんじん] の 子どもより\", \"options\": [\"日本人\", \"外国人\", \"先生\", \"大人\"], \"answer\": \"日本人\", \"explanation\": \"にほんじん viết là 日本人 (người Nhật).\"}, {\"id\": 7, \"prompt\": \"⑦ 日本人の [こども] より\", \"options\": [\"子ども\", \"女子\", \"男子\", \"学生\"], \"answer\": \"子ども\", \"explanation\": \"こども viết là 子ども (trẻ em).\"}, {\"id\": 8, \"prompt\": \"⑧ [すこし] せが 高いです\", \"options\": [\"少し\", \"多く\", \"長く\", \"早く\"], \"answer\": \"少し\", \"explanation\": \"すこし viết là 少し (cao hơn một chút).\"}, {\"id\": 9, \"prompt\": \"⑨ 少し せが [たかい] です\", \"options\": [\"高い\", \"安い\", \"長い\", \"大きい\"], \"answer\": \"高い\", \"explanation\": \"たかい viết là 高い (dáng người cao).\"}, {\"id\": 10, \"prompt\": \"⑩ いつも [げんき] です\", \"options\": [\"元気\", \"天気\", \"気分\", \"安心\"], \"answer\": \"元気\", \"explanation\": \"げんき viết là 元気 (luôn vui tươi khỏe khoắn).\"}, {\"id\": 11, \"prompt\": \"⑪ きのう はじめて [にほんじん] の 友だちが うちへ きました\", \"options\": [\"日本人\", \"外国人\", \"大人\", \"先生\"], \"answer\": \"日本人\", \"explanation\": \"にほんじん viết là 日本人 (bạn người Nhật).\"}, {\"id\": 12, \"prompt\": \"⑫ 日本人の [ともだち] が うちへ きました\", \"options\": [\"友だち\", \"友達\", \"先生\", \"人\"], \"answer\": \"友だち\", \"explanation\": \"ともだち viết là 友だち (bạn bè).\"}, {\"id\": 13, \"prompt\": \"⑬ 友だちが うちへ あそびに [き] ました\", \"options\": [\"来ました\", \"行きました\", \"帰りました\", \"出ました\"], \"answer\": \"来ました\", \"explanation\": \"きました viết là 来ました (đến nhà chơi).\"}, {\"id\": 14, \"prompt\": \"⑭ マリーは 友だちと 日本語で [はなし] ていました\", \"options\": [\"話して\", \"言って\", \"読んで\", \"聞いて\"], \"answer\": \"話して\", \"explanation\": \"はなして viết là 話して (nói chuyện bằng tiếng Nhật).\"}, {\"id\": 15, \"prompt\": \"⑮ わたしと つまは 少し [あんしん] しました\", \"options\": [\"安心\", \"安全\", \"心配\", \"元気\"], \"answer\": \"安心\", \"explanation\": \"あんしん viết là 安心 (yên tâm, an lòng).\"}]}"', 3, NOW());
